        unordered_map<long long, int> seen;  // long long: target - x may overflow int
        for (int i = 0; i < (int)nums.size(); ++i) {
            auto it = seen.find((long long)target - nums[i]);
            if (it != seen.end()) return {it->second, i};
            seen[nums[i]] = i;
        }
        return {};
    }
};

