class Solution {
    public int minDominoRotations(int[] tops, int[] bottoms) {
        int ans = Math.min(cost(tops, bottoms, tops[0]), cost(tops, bottoms, bottoms[0]));
        return ans == Integer.MAX_VALUE ? -1 : ans;
    }

    private int cost(int[] tops, int[] bottoms, int v) {
        int top = 0, bottom = 0;
        for (int i = 0; i < tops.length; i++) {
            if (tops[i] != v && bottoms[i] != v) return Integer.MAX_VALUE;
            if (tops[i] != v) top++;
            if (bottoms[i] != v) bottom++;
        }
        return Math.min(top, bottom);
    }
}

