import "math"

func minDominoRotations(tops []int, bottoms []int) int {
    cost := func(v int) int {
        top, bottom := 0, 0
        for i := range tops {
            if tops[i] != v && bottoms[i] != v {
                return math.MaxInt
            }
            if tops[i] != v {
                top++
            }
            if bottoms[i] != v {
                bottom++
            }
        }
        return min(top, bottom)
    }
    ans := min(cost(tops[0]), cost(bottoms[0]))
    if ans == math.MaxInt {
        return -1
    }
    return ans
}

