class Solution {
public:
    int shipWithinDays(vector<int>& weights, int days) {
        auto need = [&](int cap) {
            int d = 1, load = 0;
            for (int w : weights) {
                if (load + w > cap) ++d, load = 0;
                load += w;
            }
            return d;
        };
        int lo = *max_element(weights.begin(), weights.end());
        int hi = accumulate(weights.begin(), weights.end(), 0);
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (need(mid) <= days) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    }
};

