class Solution {
    public int shipWithinDays(int[] weights, int days) {
        int lo = 0, hi = 0;
        for (int w : weights) {
            lo = Math.max(lo, w);
            hi += w;
        }
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (need(weights, mid) <= days) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    }

    private int need(int[] weights, int cap) {
        int d = 1, load = 0;
        for (int w : weights) {
            if (load + w > cap) {
                d++;
                load = 0;
            }
            load += w;
        }
        return d;
    }
}

approaches.go:
func shipWithinDays(weights []int, days int) int {
    need := func(cap int) int {
        d, load := 1, 0
        for _, w := range weights {
            if load+w > cap {
                d++
                load = 0
            }
            load += w
        }
        return d
    }
    lo, hi := 0, 0
    for _, w := range weights {
        lo = max(lo, w)
        hi += w
    }
    for lo < hi {
        mid := lo + (hi-lo)/2
        if need(mid) <= days {
            hi = mid
        } else {
            lo = mid + 1
        }
    }
    return lo
}

