class Solution {
public:
    vector<bool> camelMatch(vector<string>& queries, string pattern) {
        vector<bool> res;
        for (const string& q : queries) {
            size_t j = 0;
            bool ok = true;
            for (char c : q) {
                if (j < pattern.size() && c == pattern[j]) ++j;
                else if (isupper(c)) { ok = false; break; }
            }
            res.push_back(ok && j == pattern.size());
        }
        return res;
    }
};

approaches.java:
class Solution {
    public List<Boolean> camelMatch(String[] queries, String pattern) {
        List<Boolean> res = new ArrayList<>();
        for (String q : queries) res.add(match(q, pattern));
        return res;
    }

    private boolean match(String q, String pattern) {
        int j = 0;
        for (char ch : q.toCharArray()) {
            if (j < pattern.length() && ch == pattern.charAt(j)) j++;
            else if (Character.isUpperCase(ch)) return false;
        }
        return j == pattern.length();
    }
}

approaches.go:
func camelMatch(queries []string, pattern string) []bool {
    match := func(q string) bool {
        j := 0
        for i := 0; i < len(q); i++ {
            ch := q[i]
            if j < len(pattern) && ch == pattern[j] {
                j++
            } else if ch >= 'A' && ch <= 'Z' {
                return false
            }
        }
        return j == len(pattern)
    }
    res := make([]bool, len(queries))
    for i, q := range queries {
        res[i] = match(q)
    }
    return res
}

