        for (int[] row : dp) Arrays.fill(row, 1);
        for (int i = 1; i < n; i++)
            for (int j = 0; j < i; j++) {
                int d = nums[i] - nums[j] + 500;
                dp[i][d] = dp[j][d] + 1;
                best = Math.max(best, dp[i][d]);
            }
        return best;
    }
}

approaches.go:
func longestArithSeqLength(nums []int) int {
    n, best := len(nums), 2
    dp := make([]map[int]int, n)
    for i := range dp {
        dp[i] = map[int]int{}
    }
    for i := 0; i < n; i++ {
        for j := 0; j < i; j++ {
            d := nums[i] - nums[j]
            prev, ok := dp[j][d]
            if !ok {
                prev = 1
            }
            dp[i][d] = prev + 1
            best = max(best, dp[i][d])
        }
    }
    return best
}

