import random


class Solution:
    def longestDupSubstring(self, s: str) -> str:
        MOD = (1 << 61) - 1
        base = random.randrange(256, MOD - 1)
        n = len(s)
        pre, pw = [0] * (n + 1), [1] * (n + 1)
        for i, ch in enumerate(s):
            pre[i + 1] = (pre[i] * base + ord(ch)) % MOD
            pw[i + 1] = pw[i] * base % MOD

        def find(L):
            seen = {}
            for i in range(n - L + 1):
                h = (pre[i + L] - pre[i] * pw[L]) % MOD
                j = seen.setdefault(h, i)
                if j != i and s[j:j + L] == s[i:i + L]:
                    return i
            return -1

        lo, hi, start, best = 1, n - 1, 0, 0
        while lo <= hi:
            mid = (lo + hi) // 2
            i = find(mid)
            if i >= 0:
                start, best, lo = i, mid, mid + 1
            else:
                hi = mid - 1
        return s[start:start + best]

