class Solution {
public:
    string longestDupSubstring(string s) {
        using u64 = unsigned long long;
        const u64 MOD = (1ULL << 61) - 1;
        auto mul = [&](u64 a, u64 b) { return (u64)((__uint128_t)a * b % MOD); };
        u64 base = mt19937_64(random_device{}())() % (MOD - 512) + 256;
        int n = s.size();
        vector<u64> pre(n + 1), pw(n + 1, 1);
        for (int i = 0; i < n; ++i) {
            pre[i + 1] = (mul(pre[i], base) + (unsigned char)s[i]) % MOD;
            pw[i + 1] = mul(pw[i], base);
        }
        auto find = [&](int L) {
            unordered_map<u64, int> seen;
            for (int i = 0; i + L <= n; ++i) {
                u64 h = (pre[i + L] + MOD - mul(pre[i], pw[L])) % MOD;
                auto [it, fresh] = seen.emplace(h, i);
                if (!fresh && s.compare(it->second, L, s, i, L) == 0) return i;
            }
            return -1;
        };
        int lo = 1, hi = n - 1, start = 0, best = 0;
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2, i = find(mid);
            if (i >= 0) start = i, best = mid, lo = mid + 1;
            else hi = mid - 1;
        }
        return s.substr(start, best);
    }
};

