class Solution {
    private static final long MOD = (1L << 61) - 1;
    private String s;
    private int n;
    private long[] pre, pw;

    public String longestDupSubstring(String s) {
        this.s = s;
        n = s.length();
        long base = 256 + Math.floorMod(new Random().nextLong(), MOD - 512);
        pre = new long[n + 1];
        pw = new long[n + 1];
        pw[0] = 1;
        for (int i = 0; i < n; i++) {
            pre[i + 1] = (mul(pre[i], base) + s.charAt(i)) % MOD;
            pw[i + 1] = mul(pw[i], base);
        }
        int lo = 1, hi = n - 1, start = 0, best = 0;
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2, i = find(mid);
            if (i >= 0) {
                start = i;
                best = mid;
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        return s.substring(start, start + best);
    }

    private int find(int len) {
        Map<Long, Integer> seen = new HashMap<>();
        for (int i = 0; i + len <= n; i++) {
            long h = (pre[i + len] + MOD - mul(pre[i], pw[len])) % MOD;
            Integer j = seen.putIfAbsent(h, i);
            if (j != null && s.regionMatches(j, s, i, len)) return i;
        }
        return -1;
    }

    // (a * b) mod 2^61-1 without overflow, via the 128-bit product
    private static long mul(long a, long b) {
        long hi = Math.multiplyHigh(a, b), lo = a * b;
        long r = (lo & MOD) + ((lo >>> 61) | (hi << 3));
        return r >= MOD ? r - MOD : r;
    }
}

