import (
    "math/bits"
    "math/rand"
)

func longestDupSubstring(s string) string {
    const mod = uint64(1)<<61 - 1
    mul := func(a, b uint64) uint64 {
        hi, lo := bits.Mul64(a, b)
        _, r := bits.Div64(hi, lo, mod)
        return r
    }
    base := rand.Uint64()%(mod-512) + 256
    n := len(s)
    pre, pw := make([]uint64, n+1), make([]uint64, n+1)
    pw[0] = 1
    for i := 0; i < n; i++ {
        pre[i+1] = (mul(pre[i], base) + uint64(s[i])) % mod
        pw[i+1] = mul(pw[i], base)
    }
    find := func(L int) int {
        seen := map[uint64]int{}
        for i := 0; i+L <= n; i++ {
            h := (pre[i+L] + mod - mul(pre[i], pw[L])) % mod
            if j, ok := seen[h]; ok {
                if s[j:j+L] == s[i:i+L] {
                    return i
                }
            } else {
                seen[h] = i
            }
        }
        return -1
    }
    lo, hi, start, best := 1, n-1, 0, 0
    for lo <= hi {
        mid := lo + (hi-lo)/2
        if i := find(mid); i >= 0 {
            start, best, lo = i, mid, mid+1
        } else {
            hi = mid - 1
        }
    }
    return s[start : start+best]
}

