class Solution:
    def buildTree(self, preorder: List[int], inorder: List[int]) -> Optional[TreeNode]:
        pos = {v: i for i, v in enumerate(inorder)}
        it = iter(preorder)

        def build(lo, hi):
            if lo > hi:
                return None
            node = TreeNode(next(it))
            node.left = build(lo, pos[node.val] - 1)
            node.right = build(pos[node.val] + 1, hi)
            return node

