        ans = 0
        for r1 in range(m):
            for r2 in range(r1 + 1, m + 1):
                for c1 in range(n):
                    for c2 in range(c1 + 1, n + 1):
                        if P[r2][c2] - P[r1][c2] - P[r2][c1] + P[r1][c1] == target:
