class Solution {
public:
    int numTilePossibilities(string tiles) {
        int cnt[26] = {};
        for (char ch : tiles) ++cnt[ch - 'A'];
        function<int()> dfs = [&]() {
            int total = 0;
            for (int c = 0; c < 26; ++c) {
                if (!cnt[c]) continue;
                --cnt[c];
                total += 1 + dfs();
                ++cnt[c];
            }
            return total;
        };
        return dfs();
    }
};

