class Solution {
    private final int[] cnt = new int[26];

    public int numTilePossibilities(String tiles) {
        Arrays.fill(cnt, 0);
        for (char ch : tiles.toCharArray()) cnt[ch - 'A']++;
        return dfs();
    }

