        return build(0, n - 1);
    }

    private TreeNode build(int lo, int hi) {
        if (lo > hi) return null;
        int mid = lo + (hi - lo) / 2;
        TreeNode left = build(lo, mid - 1);
        TreeNode node = new TreeNode(cur.val, left, null);
        cur = cur.next;
        node.right = build(mid + 1, hi);
        return node;
    }
}

