        a, b = str1, str2
        m, n = len(a), len(b)
        dp = [[0] * (n + 1) for _ in range(m + 1)]
        for i in range(m - 1, -1, -1):
            for j in range(n - 1, -1, -1):
                dp[i][j] = dp[i + 1][j + 1] + 1 if a[i] == b[j] else max(dp[i + 1][j], dp[i][j + 1])
        out, i, j = [], 0, 0
        while i < m and j < n:
            if a[i] == b[j]:
                out.append(a[i])
                i, j = i + 1, j + 1
            elif dp[i + 1][j] >= dp[i][j + 1]:
                out.append(a[i])
                i += 1
            else:
                out.append(b[j])
                j += 1
        return ''.join(out) + a[i:] + b[j:]

