import "strings"

func shortestCommonSupersequence(str1 string, str2 string) string {
    a, b := str1, str2
    m, n := len(a), len(b)
    dp := make([][]int, m+1)
    for i := range dp {
        dp[i] = make([]int, n+1)
    }
    for i := m - 1; i >= 0; i-- {
        for j := n - 1; j >= 0; j-- {
            if a[i] == b[j] {
                dp[i][j] = dp[i+1][j+1] + 1
            } else {
                dp[i][j] = max(dp[i+1][j], dp[i][j+1])
            }
        }
    }
    var out strings.Builder
    i, j := 0, 0
    for i < m && j < n {
        if a[i] == b[j] {
            out.WriteByte(a[i])
            i, j = i+1, j+1
        } else if dp[i+1][j] >= dp[i][j+1] {
            out.WriteByte(a[i])
            i++
        } else {
            out.WriteByte(b[j])
            j++
        }
    }
    return out.String() + a[i:] + b[j:]
