import "sort"

func carPooling(trips [][]int, capacity int) bool {
    events := make([][2]int, 0, 2*len(trips))
    for _, t := range trips {
        events = append(events, [2]int{t[1], t[0]}, [2]int{t[2], -t[0]})
    }
    // at the same stop, drop-offs (negative) come first
    sort.Slice(events, func(i, j int) bool {
        if events[i][0] != events[j][0] {
            return events[i][0] < events[j][0]
        }
        return events[i][1] < events[j][1]
    })
    cur := 0
    for _, e := range events {
        cur += e[1]
        if cur > capacity {
            return false
        }
    }
    return true
}

