public:
    int minimumSemesters(int n, vector<vector<int>>& relations) {
        vector<vector<int>> g(n + 1);
        vector<int> indeg(n + 1, 0);
        for (auto& r : relations) {
            g[r[0]].push_back(r[1]);
            ++indeg[r[1]];
        }
        vector<int> layer;
        for (int i = 1; i <= n; ++i)
            if (indeg[i] == 0) layer.push_back(i);
        int semesters = 0, taken = 0;
        while (!layer.empty()) {
            ++semesters;
            taken += layer.size();
            vector<int> nxt;
            for (int u : layer)
                for (int v : g[u])
                    if (--indeg[v] == 0) nxt.push_back(v);
            layer.swap(nxt);
        }
        return taken == n ? semesters : -1;
    }
};

