    for cur := root; cur != nil; cur = cur.Right {
        if cur.Left == nil {
            continue
        }
        p := cur.Left
        for p.Right != nil {
            p = p.Right
        }
        p.Right = cur.Right
        cur.Right, cur.Left = cur.Left, nil
    }
}

