import "math"

func stoneGameII(piles []int) int {
    n := len(piles)
    suf := make([]int, n+1)
    for i := n - 1; i >= 0; i-- {
        suf[i] = suf[i+1] + piles[i]
    }
    dp := make([][]int, n+1)
    for i := range dp {
        dp[i] = make([]int, n+1)
    }
    for i := n - 1; i >= 0; i-- {
        for m := 1; m <= n; m++ {
            if i+2*m >= n {
                dp[i][m] = suf[i]
                continue
            }
            worst := math.MaxInt
            for x := 1; x <= 2*m; x++ {
                worst = min(worst, dp[i+x][max(m, x)])
            }
            dp[i][m] = suf[i] - worst
        }
    }
    return dp[0][1]
}

