class SnapshotArray {
    private final List<int[]>[] log; // per index: sorted (snap_id, value)
    private int snapId = 0;

    public SnapshotArray(int length) {
        log = new List[length];
        for (int i = 0; i < length; i++) {
            log[i] = new ArrayList<>();
            log[i].add(new int[]{-1, 0});
        }
    }

    public void set(int index, int val) {
        List<int[]> h = log[index];
        int[] last = h.get(h.size() - 1);
        if (last[0] == snapId) last[1] = val;
        else h.add(new int[]{snapId, val});
    }

    public int snap() {
        return snapId++;
    }

    public int get(int index, int snap_id) {
        List<int[]> h = log[index];
        int lo = 0, hi = h.size(); // first entry with snap > snap_id
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (h.get(mid)[0] <= snap_id) lo = mid + 1;
            else hi = mid;
        }
        return h.get(lo - 1)[1];
    }
}

