import "sort"

type SnapshotArray struct {
    log    [][][2]int // per index: sorted (snap_id, value)
    snapId int
}

func Constructor(length int) SnapshotArray {
    log := make([][][2]int, length)
    for i := range log {
        log[i] = [][2]int{{-1, 0}}
    }
    return SnapshotArray{log: log}
}

func (this *SnapshotArray) Set(index int, val int) {
    h := this.log[index]
    if h[len(h)-1][0] == this.snapId {
        h[len(h)-1][1] = val
    } else {
        this.log[index] = append(h, [2]int{this.snapId, val})
    }
}

func (this *SnapshotArray) Snap() int {
    this.snapId++
    return this.snapId - 1
}

func (this *SnapshotArray) Get(index int, snap_id int) int {
    h := this.log[index]
    i := sort.Search(len(h), func(k int) bool { return h[k][0] > snap_id })
    return h[i-1][1]
}

