        kids[node][parts.back()] = id;
        return true;
    }

    int get(string path) {
        int node = 0;
        for (auto& p : split(path)) {
            auto it = kids[node].find(p);
            if (it == kids[node].end()) return -1;
            node = it->second;
        }
        return vals[node];
    }

private:
    vector<unordered_map<string, int>> kids;  // node -> (component -> child node)
    vector<int> vals;

    static vector<string> split(const string& path) {
        vector<string> parts;
        stringstream ss(path.substr(1));
        string s;
        while (getline(ss, s, '/')) parts.push_back(s);
        return parts;
    }
};

