func (this *FileSystem) CreatePath(path string, value int) bool {
    parts := strings.Split(path[1:], "/")
    node := this.root
    for _, p := range parts[:len(parts)-1] {
        next, ok := node.kids[p]
        if !ok {
            return false
        }
        node = next
    }
    name := parts[len(parts)-1]
    if _, ok := node.kids[name]; ok {
        return false
    }
    node.kids[name] = &dir{value: value, kids: map[string]*dir{}}
    return true
}

