func minCostToSupplyWater(n int, wells []int, pipes [][]int) int {
	edges := make([][3]int, 0, n+len(pipes))
	for i, c := range wells {
		edges = append(edges, [3]int{c, 0, i + 1})
	}
	for _, p := range pipes {
		edges = append(edges, [3]int{p[2], p[0], p[1]})
	}
	sort.Slice(edges, func(i, j int) bool { return edges[i][0] < edges[j][0] })
	parent := make([]int, n+1)
	for i := range parent {
		parent[i] = i
	}
	find := func(x int) int {
		for parent[x] != x {
			parent[x] = parent[parent[x]]
			x = parent[x]
		}
		return x
	}
	total := 0
	for _, e := range edges {
		ra, rb := find(e[1]), find(e[2])
		if ra != rb {
			parent[ra] = rb
			total += e[0]
		}
	}
	return total
