    def criticalConnections(self, n: int, connections: List[List[int]]) -> List[List[int]]:
        graph = [[] for _ in range(n)]
        for i, (a, b) in enumerate(connections):
            graph[a].append((b, i))
            graph[b].append((a, i))
        disc, low, bridges = [0] * n, [0] * n, []
        timer = 0

        def dfs(u, parent_edge):
            nonlocal timer
            timer += 1
            disc[u] = low[u] = timer
            for v, e in graph[u]:
                if e == parent_edge:
                    continue
                if disc[v]:
                    low[u] = min(low[u], disc[v])
                else:
                    dfs(v, e)
                    low[u] = min(low[u], low[v])
                    if low[v] > disc[u]:
                        bridges.append([u, v])

        dfs(0, -1)
        return bridges

