                if (ends[mid] <= startTime[k]) lo = mid + 1;
                else hi = mid;
            }
            int j = lo - 1;
            dp[t + 1] = Math.max(dp[t], dp[j] + profit[k]);
            ends[t + 1] = endTime[k];
        }
        return dp[n];
    }
