func isPalindrome(s string) bool {
	isAlnum := func(c byte) bool {
		return 'a' <= c && c <= 'z' || 'A' <= c && c <= 'Z' || '0' <= c && c <= '9'
	}
	lower := func(c byte) byte {
		if 'A' <= c && c <= 'Z' {
			return c + 'a' - 'A'
		}
		return c
	}
	i, j := 0, len(s)-1
	for i < j {
		if !isAlnum(s[i]) {
			i++
		} else if !isAlnum(s[j]) {
			j--
		} else if lower(s[i]) != lower(s[j]) {
			return false
		} else {
			i, j = i+1, j-1
		}
	}
	return true
}

