func shortestPath(grid [][]int, k int) int {
	m, n := len(grid), len(grid[0])
	if k >= m+n-3 {
		return m + n - 2
	}
	best := make([][]int, m) // most eliminations left on arrival
	for i := range best {
		best[i] = make([]int, n)
		for j := range best[i] {
			best[i][j] = -1
		}
	}
	best[0][0] = k
	q := [][3]int{{0, 0, k}}
	dirs := [5]int{0, 1, 0, -1, 0}
	for steps := 0; len(q) > 0; steps++ {
		var next [][3]int
		for _, cur := range q {
			r, c, left := cur[0], cur[1], cur[2]
			if r == m-1 && c == n-1 {
				return steps
			}
			for d := 0; d < 4; d++ {
				nr, nc := r+dirs[d], c+dirs[d+1]
				if nr < 0 || nr >= m || nc < 0 || nc >= n {
					continue
				}
				if nl := left - grid[nr][nc]; nl > best[nr][nc] {
					best[nr][nc] = nl
					next = append(next, [3]int{nr, nc, nl})
				}
			}
		}
		q = next
	}
	return -1
}

