func longestDiverseString(a int, b int, c int) string {
	type pair struct {
		left int
		ch   byte
	}
	cnt := []pair{{a, 'a'}, {b, 'b'}, {c, 'c'}}
	var res []byte
	for {
		sort.SliceStable(cnt, func(i, j int) bool { return cnt[i].left > cnt[j].left })
		placed := false
		for i := range cnt {
			p := &cnt[i]
			n := len(res)
			if p.left == 0 || n >= 2 && res[n-1] == p.ch && res[n-2] == p.ch {
				continue
			}
			res = append(res, p.ch)
			p.left--
			placed = true
			break
		}
		if !placed {
			return string(res)
		}
	}
}

