public:
    int longestSubarray(vector<int>& nums, int limit) {
        deque<int> mx, mn;
        int left = 0, ans = 0;
        for (int right = 0; right < (int)nums.size(); ++right) {
            int x = nums[right];
            while (!mx.empty() && mx.back() < x) mx.pop_back();
            while (!mn.empty() && mn.back() > x) mn.pop_back();
            mx.push_back(x);
            mn.push_back(x);
            while (mx.front() - mn.front() > limit) {
                if (mx.front() == nums[left]) mx.pop_front();
                if (mn.front() == nums[left]) mn.pop_front();
                ++left;
            }
            ans = max(ans, right - left + 1);
        }
        return ans;
    }
};

