	left, ans := 0, 0
	for right, x := range nums {
		for len(mx) > 0 && mx[len(mx)-1] < x {
			mx = mx[:len(mx)-1]
		}
		for len(mn) > 0 && mn[len(mn)-1] > x {
			mn = mn[:len(mn)-1]
		}
		mx = append(mx, x)
		mn = append(mn, x)
		for mx[0]-mn[0] > limit {
			if mx[0] == nums[left] {
				mx = mx[1:]
			}
			if mn[0] == nums[left] {
				mn = mn[1:]
			}
			left++
		}
		ans = max(ans, right-left+1)
	}
	return ans
}

