        cap = capacity;
    }

    public int get(int key) {
        Integer v = cache.get(key);
        return v == null ? -1 : v;
    }

    public void put(int key, int value) {
        cache.put(key, value);
        if (cache.size() > cap) cache.remove(cache.keySet().iterator().next());
    }
