	if e, ok := this.pos[key]; ok {
		e.Value.(*entry).val = value
		this.items.MoveToFront(e)
		return
	}
	this.pos[key] = this.items.PushFront(&entry{key, value})
	if this.items.Len() > this.cap {
		last := this.items.Back()
		delete(this.pos, last.Value.(*entry).key)
		this.items.Remove(last)
	}
