func checkIfPrerequisite(numCourses int, prerequisites [][]int, queries [][]int) []bool {
	n := numCourses
	g := make([][]int, n)
	indeg := make([]int, n)
	for _, p := range prerequisites {
		g[p[0]] = append(g[p[0]], p[1])
		indeg[p[1]]++
	}
	words := (n + 63) / 64
	anc := make([][]uint64, n) // bit u of anc[v] set <=> u is a prerequisite of v
	for i := range anc {
		anc[i] = make([]uint64, words)
	}
	var q []int
	for i := 0; i < n; i++ {
		if indeg[i] == 0 {
			q = append(q, i)
		}
	}
	for len(q) > 0 {
		u := q[0]
		q = q[1:]
		for _, v := range g[u] {
			for w := range anc[v] {
				anc[v][w] |= anc[u][w]
			}
			anc[v][u/64] |= 1 << (u % 64)
			indeg[v]--
			if indeg[v] == 0 {
				q = append(q, v)
			}
		}
	}
	res := make([]bool, len(queries))
	for i, qr := range queries {
		u, v := qr[0], qr[1]
		res[i] = anc[v][u/64]>>(u%64)&1 == 1
	}
	return res
