        if m * k > len(bloomDay):
            return -1

        def can(day):
            bouquets = run = 0
            for d in bloomDay:
                run = run + 1 if d <= day else 0
                if run == k:
                    bouquets += 1
                    run = 0
            return bouquets >= m

