                long b = st.pop(), a = st.pop();
                switch (t.charAt(0)) {
                    case '+' -> st.push(a + b);
                    case '-' -> st.push(a - b);
                    case '*' -> st.push(a * b);
                    default -> st.push(a / b); // Java division truncates toward zero
                }
            } else {
                st.push(Long.parseLong(t));
            }
        }
        return (int) (long) st.pop();
    }
}

