class Solution {
public:
    int maxProduct(vector<int>& nums) {
        // double: some judge inputs push the running min product past 64-bit range
        double ans = nums[0], hi = nums[0], lo = nums[0];
        for (int i = 1; i < (int)nums.size(); ++i) {
            double x = nums[i];
            if (x < 0) swap(hi, lo);
            hi = max(x, hi * x);
            lo = min(x, lo * x);
            ans = max(ans, hi);
        }
        return (int)ans;
    }
};

