    public int maxProduct(int[] nums) {
        // double: some judge inputs push the running min product past 64-bit range
        double ans = nums[0], hi = nums[0], lo = nums[0];
        for (int i = 1; i < nums.length; i++) {
            double x = nums[i];
            if (x < 0) {
                double t = hi;
                hi = lo;
                lo = t;
            }
            hi = Math.max(x, hi * x);
            lo = Math.min(x, lo * x);
            ans = Math.max(ans, hi);
        }
        return (int) ans;
    }
}

