class Solution:
    def countPairs(self, root: Optional[TreeNode], distance: int) -> int:
        ans = 0

        def dfs(node):
            # cnt[d] = number of leaves under node that are d edges from node's parent
            nonlocal ans
            cnt = [0] * (distance + 1)
            if not node:
                return cnt
            if not node.left and not node.right:
                cnt[1] = 1
                return cnt
            left, right = dfs(node.left), dfs(node.right)
            for i in range(1, distance):
                for j in range(1, distance - i + 1):
                    ans += left[i] * right[j]
            for d in range(1, distance):
                cnt[d + 1] = left[d] + right[d]
            return cnt

        dfs(root)
        return ans

