class Solution {
public:
    int countPairs(TreeNode* root, int distance) {
        int ans = 0;
        dfs(root, distance, ans);
        return ans;
    }

private:
    // cnt[d] = number of leaves under node that are d edges from node's parent
    vector<int> dfs(TreeNode* node, int D, int& ans) {
        vector<int> cnt(D + 1, 0);
        if (!node) return cnt;
        if (!node->left && !node->right) {
            cnt[1] = 1;
            return cnt;
        }
        vector<int> L = dfs(node->left, D, ans), R = dfs(node->right, D, ans);
        for (int i = 1; i < D; ++i)
            for (int j = 1; i + j <= D; ++j)
                ans += L[i] * R[j];
        for (int d = 1; d < D; ++d) cnt[d + 1] = L[d] + R[d];
        return cnt;
    }
};

