        if (node.left == null && node.right == null) {
            cnt[1] = 1;
            return cnt;
        }
        int[] L = dfs(node.left, D), R = dfs(node.right, D);
        for (int i = 1; i < D; i++)
            for (int j = 1; i + j <= D; j++)
                ans += L[i] * R[j];
        for (int d = 1; d < D; d++) cnt[d + 1] = L[d] + R[d];
        return cnt;
    }
}

