func (this *MinStack) Push(val int) {
	m := val
	if len(this.st) > 0 {
		m = min(val, this.st[len(this.st)-1][1])
	}
	this.st = append(this.st, [2]int{val, m})
}

func (this *MinStack) Pop() {
	this.st = this.st[:len(this.st)-1]
