class Solution:
    def maxDistance(self, position: List[int], m: int) -> int:
        position.sort()

        def can(gap):
            count, last = 1, position[0]
            for p in position[1:]:
                if p - last >= gap:
                    count += 1
                    last = p
            return count >= m

        lo, hi = 1, (position[-1] - position[0]) // (m - 1)
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if can(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

