            int count = 1, last = position[0];
            for (int p : position)
                if (p - last >= gap) { ++count; last = p; }
            return count >= m;
        };
        int lo = 1, hi = (position.back() - position[0]) / (m - 1);
        while (lo < hi) {
            int mid = lo + (hi - lo + 1) / 2;
            if (can(mid)) lo = mid;
            else hi = mid - 1;
        }
        return lo;
