class Solution {
    public int maxDistance(int[] position, int m) {
        Arrays.sort(position);
        int lo = 1, hi = (position[position.length - 1] - position[0]) / (m - 1);
        while (lo < hi) {
            int mid = lo + (hi - lo + 1) / 2;
            if (can(position, m, mid)) lo = mid;
            else hi = mid - 1;
        }
        return lo;
    }

    private boolean can(int[] position, int m, int gap) {
        int count = 1, last = position[0];
        for (int p : position) {
            if (p - last >= gap) {
                count++;
                last = p;
            }
        }
        return count >= m;
    }
}

