import "sort"

func minCostConnectPoints(points [][]int) int {
	n := len(points)
	abs := func(x int) int {
		if x < 0 {
			return -x
		}
		return x
	}
	edges := make([][3]int, 0, n*(n-1)/2)
	for i := 0; i < n; i++ {
		for j := i + 1; j < n; j++ {
			edges = append(edges, [3]int{abs(points[i][0]-points[j][0]) + abs(points[i][1]-points[j][1]), i, j})
		}
	}
	sort.Slice(edges, func(a, b int) bool { return edges[a][0] < edges[b][0] })
	parent := make([]int, n)
	for i := range parent {
		parent[i] = i
	}
	find := func(x int) int {
		for parent[x] != x {
			parent[x] = parent[parent[x]]
			x = parent[x]
		}
		return x
	}
	total, used := 0, 0
	for _, e := range edges {
		if used == n-1 {
			break
		}
		ri, rj := find(e[1]), find(e[2])
		if ri == rj {
			continue
		}
		parent[ri] = rj
		total += e[0]
		used++
	}
	return total
}

