class Solution:
    def minCostConnectPoints(self, points: List[List[int]]) -> int:
        n = len(points)
        dist = [float('inf')] * n  # cheapest edge from the tree to each point
        in_tree = [False] * n
        dist[0] = 0
        total = 0
        for _ in range(n):
            u = min((i for i in range(n) if not in_tree[i]), key=dist.__getitem__)
            in_tree[u] = True
            total += dist[u]
            ux, uy = points[u]
            for v in range(n):
                if not in_tree[v]:
                    d = abs(ux - points[v][0]) + abs(uy - points[v][1])
                    if d < dist[v]:
                        dist[v] = d
        return total

