class Solution:
    def lengthOfLongestSubstringTwoDistinct(self, s: str) -> int:
        count = {}
        left = ans = 0
        for right, c in enumerate(s):
            count[c] = count.get(c, 0) + 1
            while len(count) > 2:
                out = s[left]
                count[out] -= 1
                if count[out] == 0:
                    del count[out]
                left += 1
            ans = max(ans, right - left + 1)
        return ans

