class Solution {
public:
    int lengthOfLongestSubstringTwoDistinct(string s) {
        unordered_map<char, int> count;
        int left = 0, ans = 0;
        for (int right = 0; right < (int)s.size(); ++right) {
            ++count[s[right]];
            while (count.size() > 2) {
                if (--count[s[left]] == 0) count.erase(s[left]);
                ++left;
            }
            ans = max(ans, right - left + 1);
        }
        return ans;
    }
};

