	count := map[byte]int{}
	left, ans := 0, 0
	for right := 0; right < len(s); right++ {
		count[s[right]]++
		for len(count) > 2 {
			out := s[left]
			count[out]--
			if count[out] == 0 {
				delete(count, out)
			}
			left++
		}
		ans = max(ans, right-left+1)
	}
	return ans
}

