class Solution:
    def maxUniqueSplit(self, s: str) -> int:
        n, used, best = len(s), set(), 0

        def dfs(i: int) -> None:
            nonlocal best
            if len(used) + (n - i) <= best:
                return
            if i == n:
                best = len(used)
                return
            for j in range(i + 1, n + 1):
                piece = s[i:j]
                if piece not in used:
                    used.add(piece)
                    dfs(j)
                    used.remove(piece)

        dfs(0)
        return best

