class Solution {
    unordered_set<string> used;
    int best = 0;

    void dfs(const string& s, int i) {
        int n = s.size();
        if ((int)used.size() + n - i <= best) return;
        if (i == n) { best = used.size(); return; }
        for (int j = i + 1; j <= n; ++j) {
            string piece = s.substr(i, j - i);
            if (used.insert(piece).second) {
                dfs(s, j);
                used.erase(piece);
            }
        }
    }

public:
    int maxUniqueSplit(string s) {
        dfs(s, 0);
        return best;
    }
};

