    }

    private void dfs(String s, int i) {
        int n = s.length();
        if (used.size() + n - i <= best) return;
        if (i == n) {
            best = used.size();
            return;
        }
        for (int j = i + 1; j <= n; j++) {
            String piece = s.substring(i, j);
            if (used.add(piece)) {
                dfs(s, j);
                used.remove(piece);
            }
        }
    }
}

