		if i == n {
			best = len(used)
			return
		}
		for j := i + 1; j <= n; j++ {
			piece := s[i:j]
			if !used[piece] {
				used[piece] = true
				dfs(j)
				delete(used, piece)
			}
		}
	}
	dfs(0)
	return best
