	for i := range dist {
		dist[i] = make([]int, n)
		for j := range dist[i] {
			dist[i][j] = math.MaxInt
		}
	}
	dist[0][0] = 0
	h := &cellHeap{{0, 0, 0}}
	for h.Len() > 0 {
		top := heap.Pop(h).([3]int)
		d, r, c := top[0], top[1], top[2]
		if r == m-1 && c == n-1 {
			return d
		}
		if d > dist[r][c] {
			continue
		}
		for _, dir := range dirs {
			nr, nc := r+dir[0], c+dir[1]
			if nr < 0 || nr >= m || nc < 0 || nc >= n {
				continue
			}
			nd := max(d, abs(heights[nr][nc]-heights[r][c]))
			if nd < dist[nr][nc] {
				dist[nr][nc] = nd
				heap.Push(h, [3]int{nd, nr, nc})
			}
		}
	}
	return 0
}

