type minHeap struct{ sort.IntSlice }

func (h *minHeap) Push(x interface{}) { h.IntSlice = append(h.IntSlice, x.(int)) }
func (h *minHeap) Pop() interface{} {
	a := h.IntSlice
	x := a[len(a)-1]
	h.IntSlice = a[:len(a)-1]
	return x
}

