import "strconv"

func fractionToDecimal(numerator int, denominator int) string {
	if numerator == 0 {
		return "0"
	}
	res := []byte{}
	if (numerator < 0) != (denominator < 0) {
		res = append(res, '-')
	}
	n, d := numerator, denominator
	if n < 0 {
		n = -n
	}
	if d < 0 {
		d = -d
	}
	res = strconv.AppendInt(res, int64(n/d), 10)
	rem := n % d
	if rem == 0 {
		return string(res)
	}
	res = append(res, '.')
	pos := map[int]int{} // remainder -> index of the digit it produces
	for rem != 0 {
		if _, ok := pos[rem]; ok {
			break
		}
		pos[rem] = len(res)
		rem *= 10
		res = append(res, byte('0'+rem/d))
		rem %= d
	}
	if rem != 0 {
		i := pos[rem]
		return string(res[:i]) + "(" + string(res[i:]) + ")"
	}
	return string(res)
}

