        }
        return n - best;
    }

    // res[i] = length of the longest strictly increasing subsequence ending at arr[i]
    private int[] lisEnding(int[] arr) {
        int[] tails = new int[arr.length], res = new int[arr.length];
        int len = 0;
        for (int i = 0; i < arr.length; i++) {
            int lo = 0, hi = len; // lower_bound of arr[i] in tails[0, len)
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (tails[mid] < arr[i]) lo = mid + 1;
                else hi = mid;
            }
            tails[lo] = arr[i];
            if (lo == len) len++;
            res[i] = lo + 1;
        }
        return res;
    }
}

