import "sort"

// lisEnding returns, for each i, the length of the longest strictly increasing subsequence ending at arr[i].
func lisEnding(arr []int) []int {
	var tails []int
	res := make([]int, len(arr))
	for i, v := range arr {
		k := sort.SearchInts(tails, v)
		if k == len(tails) {
			tails = append(tails, v)
		} else {
			tails[k] = v
		}
		res[i] = k + 1
	}
	return res
}

func minimumMountainRemovals(nums []int) int {
	n, best := len(nums), 0
	rev := make([]int, n)
	for i, v := range nums {
		rev[n-1-i] = v
	}
	inc, decRev := lisEnding(nums), lisEnding(rev)
	for i := 0; i < n; i++ {
		dec := decRev[n-1-i]
		if inc[i] > 1 && dec > 1 {
			best = max(best, inc[i]+dec-1)
		}
	}
	return n - best
}

