		mid := lo + (hi-lo)/2
		ops := 0
		for _, x := range nums {
			ops += (x - 1) / mid
		}
		if ops <= maxOperations {
			hi = mid
		} else {
			lo = mid + 1
		}
	}
	return lo
}

