class Solution:
    def maxValue(self, n: int, index: int, maxSum: int) -> int:
        def side(v, length):  # smallest sum of `length` cells stepping down from v - 1, floored at 1
            if length <= v - 1:
                return (2 * v - 1 - length) * length // 2
            return (v - 1) * v // 2 + (length - v + 1)

        lo, hi = 1, maxSum
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if mid + side(mid, index) + side(mid, n - 1 - index) <= maxSum:
                lo = mid
            else:
                hi = mid - 1
        return lo

