import (
	"container/heap"
	"sort"
)

// taskHeap holds (duration, index) pairs, smallest first.
type taskHeap [][2]int

func (h taskHeap) Len() int { return len(h) }
func (h taskHeap) Less(i, j int) bool {
	if h[i][0] != h[j][0] {
		return h[i][0] < h[j][0]
	}
	return h[i][1] < h[j][1]
}
func (h taskHeap) Swap(i, j int)       { h[i], h[j] = h[j], h[i] }
func (h *taskHeap) Push(x interface{}) { *h = append(*h, x.([2]int)) }
func (h *taskHeap) Pop() interface{} {
	old := *h
	x := old[len(old)-1]
	*h = old[:len(old)-1]
	return x
}

func getOrder(tasks [][]int) []int {
	n := len(tasks)
	order := make([]int, n)
	for i := range order {
		order[i] = i
	}
	sort.SliceStable(order, func(a, b int) bool { return tasks[order[a]][0] < tasks[order[b]][0] })
	h := &taskHeap{}
	res := make([]int, 0, n)
	t, i := 0, 0
	for len(res) < n {
		if h.Len() == 0 && t < tasks[order[i]][0] {
			t = tasks[order[i]][0] // CPU idle: jump to the next arrival
		}
		for i < n && tasks[order[i]][0] <= t {
			heap.Push(h, [2]int{tasks[order[i]][1], order[i]})
			i++
		}
		top := heap.Pop(h).([2]int)
		t += top[0]
		res = append(res, top[1])
	}
	return res
}

