import (
	"container/heap"
	"sort"
)

// sizeHeap holds (size, right end) pairs, smallest size first.
type sizeHeap [][2]int

func (h sizeHeap) Len() int { return len(h) }
func (h sizeHeap) Less(i, j int) bool {
	if h[i][0] != h[j][0] {
		return h[i][0] < h[j][0]
	}
	return h[i][1] < h[j][1]
}
func (h sizeHeap) Swap(i, j int)       { h[i], h[j] = h[j], h[i] }
func (h *sizeHeap) Push(x interface{}) { *h = append(*h, x.([2]int)) }
func (h *sizeHeap) Pop() interface{} {
	old := *h
	x := old[len(old)-1]
	*h = old[:len(old)-1]
	return x
}

func minInterval(intervals [][]int, queries []int) []int {
	sort.Slice(intervals, func(a, b int) bool {
		if intervals[a][0] != intervals[b][0] {
			return intervals[a][0] < intervals[b][0]
		}
		return intervals[a][1] < intervals[b][1]
	})
	res := make([]int, len(queries))
	order := make([]int, len(queries))
	for i := range res {
		res[i] = -1
		order[i] = i
	}
	sort.Slice(order, func(a, b int) bool { return queries[order[a]] < queries[order[b]] })
	h := &sizeHeap{}
	i := 0
	for _, qi := range order {
		q := queries[qi]
		for i < len(intervals) && intervals[i][0] <= q {
			l, r := intervals[i][0], intervals[i][1]
			heap.Push(h, [2]int{r - l + 1, r})
			i++
		}
		for h.Len() > 0 && (*h)[0][1] < q {
			heap.Pop(h)
		}
		if h.Len() > 0 {
			res[qi] = (*h)[0][0]
		}
	}
	return res
}

