class RangeFreqQuery {
    private final Map<Integer, List<Integer>> pos = new HashMap<>();

    public RangeFreqQuery(int[] arr) {
        for (int i = 0; i < arr.length; i++) pos.computeIfAbsent(arr[i], key -> new ArrayList<>()).add(i);
    }

    public int query(int left, int right, int value) {
        List<Integer> idx = pos.getOrDefault(value, List.of());
        return lowerBound(idx, right + 1) - lowerBound(idx, left);
    }

    // First index whose element is >= x.
    private static int lowerBound(List<Integer> a, int x) {
        int lo = 0, hi = a.size();
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (a.get(mid) < x) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }
}

