class Solution:
    def subArrayRanges(self, nums: List[int]) -> int:
        def sum_of_max(a: List[int]) -> int:
            n, res, stack = len(a), 0, []
            for i in range(n + 1):
                while stack and (i == n or a[stack[-1]] <= a[i]):
                    j = stack.pop()
                    left = stack[-1] if stack else -1
                    res += a[j] * (j - left) * (i - j)
