    static long long sumOfMax(const vector<long long>& a) {
        int n = a.size();
        long long res = 0;
        vector<int> stack;
        for (int i = 0; i <= n; ++i) {
            while (!stack.empty() && (i == n || a[stack.back()] <= a[i])) {
                int j = stack.back();
                stack.pop_back();
                int left = stack.empty() ? -1 : stack.back();
                res += a[j] * (j - left) * (i - j);
            }
            stack.push_back(i);
        }
        return res;
    }

