class Solution {
    public long subArrayRanges(int[] nums) {
        long[] neg = new long[nums.length], pos = new long[nums.length];
        for (int i = 0; i < nums.length; i++) {
            pos[i] = nums[i];
            neg[i] = -(long) nums[i];
        }
        return sumOfMax(pos) + sumOfMax(neg);
    }

    // Sum over all subarrays of their maximum, via each element's span as the max.
    private long sumOfMax(long[] a) {
        int n = a.length;
        long res = 0;
        int[] stack = new int[n + 1];
        int top = 0;
        for (int i = 0; i <= n; i++) {
            while (top > 0 && (i == n || a[stack[top - 1]] <= a[i])) {
                int j = stack[--top];
                int left = top > 0 ? stack[top - 1] : -1;
                res += a[j] * (j - left) * (i - j);
            }
            stack[top++] = i;
        }
        return res;
    }
}

