		for len(stack) > 0 && (i == n || a[stack[len(stack)-1]] <= a[i]) {
			j := stack[len(stack)-1]
			stack = stack[:len(stack)-1]
			left := -1
			if len(stack) > 0 {
				left = stack[len(stack)-1]
			}
			res += a[j] * (j - left) * (i - j)
		}
		stack = append(stack, i)
	}
