    void dfs(vector<vector<char>>& board, int i, int j, Trie* parent) {
        char ch = board[i][j];
        Trie* node = parent->next[ch - 'a'].get();
        if (!node->word.empty()) {
            found.push_back(node->word);
            node->word.clear();
        }
        board[i][j] = '#';
        static const int d[5] = {0, 1, 0, -1, 0};
        for (int k = 0; k < 4; ++k) {
