            if (x >= 0 && x < (int)board.size() && y >= 0 && y < (int)board[0].size() &&
                board[x][y] != '#' && node->next[board[x][y] - 'a'])
                dfs(board, x, y, node);
        }
        board[i][j] = ch;
        if (node->empty()) parent->next[ch - 'a'].reset();
