class Solution {
    private static class Trie {
        Trie[] next = new Trie[26];
        int children;
        String word;
    }

    private char[][] board;
    private final List<String> found = new ArrayList<>();

    public List<String> findWords(char[][] board, String[] words) {
        Trie root = new Trie();
        for (String w : words) {
            Trie node = root;
            for (char ch : w.toCharArray()) {
                int c = ch - 'a';
                if (node.next[c] == null) {
                    node.next[c] = new Trie();
                    node.children++;
                }
                node = node.next[c];
            }
            node.word = w;
        }
        this.board = board;
        for (int i = 0; i < board.length; i++) {
            for (int j = 0; j < board[0].length; j++) {
                if (root.next[board[i][j] - 'a'] != null) dfs(i, j, root);
            }
        }
        return found;
    }

    private void dfs(int i, int j, Trie parent) {
        char ch = board[i][j];
        Trie node = parent.next[ch - 'a'];
        if (node.word != null) {
            found.add(node.word);
            node.word = null;
        }
        board[i][j] = '#';
        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        for (int[] d : dirs) {
            int x = i + d[0], y = j + d[1];
            if (x >= 0 && x < board.length && y >= 0 && y < board[0].length
                    && board[x][y] != '#' && node.next[board[x][y] - 'a'] != null) {
                dfs(x, y, node);
            }
        }
        board[i][j] = ch;
        // Prune exhausted branches so later searches skip them.
        if (node.children == 0 && node.word == null) {
            parent.next[ch - 'a'] = null;
            parent.children--;
        }
    }
}

