class Solution:
    def longestPalindrome(self, words: List[str]) -> int:
        cnt = Counter(words)
        length, has_center = 0, False
        for w, c in cnt.items():
            if w[0] == w[1]:
                length += c // 2 * 4
                has_center |= c % 2 == 1
            elif w < w[::-1]:
                length += min(c, cnt[w[::-1]]) * 4
        return length + (2 if has_center else 0)

