class Solution {
    public long minimumTime(int[] time, int totalTrips) {
        int minT = Integer.MAX_VALUE;
        for (int t : time) minT = Math.min(minT, t);
        long lo = 1, hi = (long) minT * totalTrips;
        while (lo < hi) {
            long mid = lo + (hi - lo) / 2;
            if (trips(time, mid, totalTrips) >= totalTrips) {
                hi = mid;
            } else {
                lo = mid + 1;
            }
        }
        return lo;
    }

    // Trips finished by time `mid`, stopping early once `need` is reached to avoid overflow.
    private long trips(int[] time, long mid, long need) {
        long sum = 0;
        for (int t : time) {
            sum += mid / t;
            if (sum >= need) break;
        }
        return sum;
    }
}

