	enough := func(mid int) bool {
		sum := 0
		for _, t := range time {
			sum += mid / t
			if sum >= totalTrips {
				return true
			}
		}
		return false
	}
	lo, hi := 1, minT*totalTrips
	for lo < hi {
		mid := (lo + hi) / 2
		if enough(mid) {
			hi = mid
		} else {
			lo = mid + 1
		}
	}
