        auto bucketOf = [&](long long x) { return x >= 0 ? x / width : (x + 1) / width - 1; };
        unordered_map<long long, long long> buckets;
        for (int i = 0; i < (int)nums.size(); ++i) {
            long long x = nums[i], b = bucketOf(x);
            if (buckets.count(b)) return true;
            auto it = buckets.find(b - 1);
            if (it != buckets.end() && x - it->second <= valueDiff) return true;
            it = buckets.find(b + 1);
            if (it != buckets.end() && it->second - x <= valueDiff) return true;
            buckets[b] = x;
            if (i >= indexDiff) buckets.erase(bucketOf(nums[i - indexDiff]));
        }
        return false;
