            if (buckets.containsKey(b)) return true;
            Long lower = buckets.get(b - 1), upper = buckets.get(b + 1);
            if (lower != null && x - lower <= valueDiff) return true;
            if (upper != null && upper - x <= valueDiff) return true;
            buckets.put(b, x);
            if (i >= indexDiff) buckets.remove(Math.floorDiv((long) nums[i - indexDiff], width));
        }
        return false;
