func floorDiv(a, b int) int {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

func containsNearbyAlmostDuplicate(nums []int, indexDiff int, valueDiff int) bool {
	width := valueDiff + 1
	buckets := map[int]int{}
	for i, x := range nums {
		b := floorDiv(x, width)
		if _, ok := buckets[b]; ok {
			return true
		}
		if y, ok := buckets[b-1]; ok && x-y <= valueDiff {
			return true
		}
		if y, ok := buckets[b+1]; ok && y-x <= valueDiff {
			return true
		}
		buckets[b] = x
		if i >= indexDiff {
			delete(buckets, floorDiv(nums[i-indexDiff], width))
		}
	}
	return false
