class Solution:
    def mergeKLists(self, lists: List[Optional[ListNode]]) -> Optional[ListNode]:
        def merge2(a, b):
            dummy = tail = ListNode()
            while a and b:
                if a.val <= b.val:
                    tail.next, a = a, a.next
                else:
                    tail.next, b = b, b.next
                tail = tail.next
            tail.next = a or b
            return dummy.next

        def solve(lo, hi):
            if lo == hi:
                return lists[lo]
            mid = (lo + hi) // 2
            return merge2(solve(lo, mid), solve(mid + 1, hi))

        return solve(0, len(lists) - 1) if lists else None

