class Solution {
    ListNode* merge2(ListNode* a, ListNode* b) {
        ListNode dummy;
        ListNode* tail = &dummy;
        while (a && b) {
            if (a->val <= b->val) tail->next = a, a = a->next;
            else tail->next = b, b = b->next;
            tail = tail->next;
        }
        tail->next = a ? a : b;
        return dummy.next;
    }
    ListNode* solve(vector<ListNode*>& lists, int lo, int hi) {
        if (lo == hi) return lists[lo];
        int mid = (lo + hi) / 2;
        return merge2(solve(lists, lo, mid), solve(lists, mid + 1, hi));
    }
public:
    ListNode* mergeKLists(vector<ListNode*>& lists) {
        return lists.empty() ? nullptr : solve(lists, 0, (int)lists.size() - 1);
    }
};

