func kthSmallest(root *TreeNode, k int) int {
    var st []*TreeNode
    node := root
    for {
        for node != nil {
            st = append(st, node)
            node = node.Left
        }
        node = st[len(st)-1]
        st = st[:len(st)-1]
        k--
        if k == 0 {
            return node.Val
        }
        node = node.Right
    }
}

