import "sort"

func successfulPairs(spells []int, potions []int, success int64) []int {
    sort.Ints(potions)
    m := len(potions)
    res := make([]int, len(spells))
    for i, s := range spells {
        need := (int(success) + s - 1) / s
        res[i] = m - sort.SearchInts(potions, need)
    }
    return res
}

