class FoodRatings {
    private record Entry(int rating, String food) {}

    private final Map<String, Integer> rating = new HashMap<>();
    private final Map<String, String> cuisineOf = new HashMap<>();
    private final Map<String, PriorityQueue<Entry>> heaps = new HashMap<>();

    public FoodRatings(String[] foods, String[] cuisines, int[] ratings) {
        for (int i = 0; i < foods.length; i++) {
            rating.put(foods[i], ratings[i]);
            cuisineOf.put(foods[i], cuisines[i]);
            heaps.computeIfAbsent(cuisines[i], c -> new PriorityQueue<>(
                    (a, b) -> a.rating() != b.rating() ? Integer.compare(b.rating(), a.rating())
                                                       : a.food().compareTo(b.food())))
                 .offer(new Entry(ratings[i], foods[i]));
        }
    }

    public void changeRating(String food, int newRating) {
        rating.put(food, newRating);
        heaps.get(cuisineOf.get(food)).offer(new Entry(newRating, food));
    }

    public String highestRated(String cuisine) {
        PriorityQueue<Entry> h = heaps.get(cuisine);
        while (h.peek().rating() != rating.get(h.peek().food())) h.poll();
        return h.peek().food();
    }
}

