import "container/heap"

type entry struct {
    rating int
    food   string
}

type entryHeap []entry

func (h entryHeap) Len() int { return len(h) }
func (h entryHeap) Less(i, j int) bool {
    if h[i].rating != h[j].rating {
        return h[i].rating > h[j].rating
    }
    return h[i].food < h[j].food
}
func (h entryHeap) Swap(i, j int) { h[i], h[j] = h[j], h[i] }
func (h *entryHeap) Push(x any)   { *h = append(*h, x.(entry)) }
func (h *entryHeap) Pop() any {
    old := *h
    x := old[len(old)-1]
    *h = old[:len(old)-1]
    return x
}

type FoodRatings struct {
    rating    map[string]int
    cuisineOf map[string]string
    heaps     map[string]*entryHeap
}

func Constructor(foods []string, cuisines []string, ratings []int) FoodRatings {
    fr := FoodRatings{map[string]int{}, map[string]string{}, map[string]*entryHeap{}}
    for i, f := range foods {
        fr.rating[f] = ratings[i]
        fr.cuisineOf[f] = cuisines[i]
        if fr.heaps[cuisines[i]] == nil {
            fr.heaps[cuisines[i]] = &entryHeap{}
        }
        heap.Push(fr.heaps[cuisines[i]], entry{ratings[i], f})
    }
    return fr
}

func (this *FoodRatings) ChangeRating(food string, newRating int) {
    this.rating[food] = newRating
    heap.Push(this.heaps[this.cuisineOf[food]], entry{newRating, food})
}

func (this *FoodRatings) HighestRated(cuisine string) string {
    h := this.heaps[cuisine]
    for (*h)[0].rating != this.rating[(*h)[0].food] {
        heap.Pop(h)
    }
    return (*h)[0].food
}

