    h := &maxHeap{}
    res := make([]int, 0, len(nums)-k+1)
    for i, x := range nums {
        heap.Push(h, pair{x, i})
        if i >= k-1 {
            for (*h)[0].idx <= i-k {
                heap.Pop(h)
            }
            res = append(res, (*h)[0].val)
        }
    }
    return res
