        if ((int)rows.size() < k || (int)cols.size() < k) return {};
        vector<int> colOf(k + 1);
        for (int j = 0; j < k; ++j) colOf[cols[j]] = j;
        vector<vector<int>> res(k, vector<int>(k, 0));
        for (int i = 0; i < k; ++i) res[i][colOf[rows[i]]] = rows[i];
        return res;
