class Solution {
    private List<Integer> topo(int k, int[][] conds) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int v = 0; v <= k; v++) adj.add(new ArrayList<>());
        int[] indeg = new int[k + 1];
        for (int[] c : conds) {
            adj.get(c[0]).add(c[1]);
            indeg[c[1]]++;
        }
        List<Integer> order = new ArrayList<>();
        for (int v = 1; v <= k; v++)
            if (indeg[v] == 0) order.add(v);
        for (int i = 0; i < order.size(); i++)
            for (int v : adj.get(order.get(i)))
                if (--indeg[v] == 0) order.add(v);
        return order;
    }

    public int[][] buildMatrix(int k, int[][] rowConditions, int[][] colConditions) {
        List<Integer> rows = topo(k, rowConditions), cols = topo(k, colConditions);
        if (rows.size() < k || cols.size() < k) return new int[0][];
        int[] colOf = new int[k + 1];
        for (int j = 0; j < k; j++) colOf[cols.get(j)] = j;
        int[][] res = new int[k][k];
        for (int i = 0; i < k; i++) res[i][colOf[rows.get(i)]] = rows.get(i);
        return res;
    }
}

