func topo(k int, conds [][]int) []int {
    adj := make([][]int, k+1)
    indeg := make([]int, k+1)
    for _, c := range conds {
        adj[c[0]] = append(adj[c[0]], c[1])
        indeg[c[1]]++
    }
    var order []int
    for v := 1; v <= k; v++ {
        if indeg[v] == 0 {
            order = append(order, v)
        }
    }
    for i := 0; i < len(order); i++ {
        for _, v := range adj[order[i]] {
            indeg[v]--
            if indeg[v] == 0 {
                order = append(order, v)
            }
        }
    }
    return order
}

func buildMatrix(k int, rowConditions [][]int, colConditions [][]int) [][]int {
    rows, cols := topo(k, rowConditions), topo(k, colConditions)
    if len(rows) < k || len(cols) < k {
        return [][]int{}
    }
    colOf := make([]int, k+1)
    for j, v := range cols {
        colOf[v] = j
    }
    res := make([][]int, k)
    for i := range res {
        res[i] = make([]int, k)
    }
    for i, v := range rows {
        res[i][colOf[v]] = v
    }
    return res
}

