class Solution {
    public int mostBooked(int n, int[][] meetings) {
        Arrays.sort(meetings, (a, b) -> Integer.compare(a[0], b[0]));
        PriorityQueue<Integer> freeRooms = new PriorityQueue<>();
        for (int i = 0; i < n; i++) freeRooms.offer(i);
        // busy rooms as {endTime, room}
        PriorityQueue<long[]> busy = new PriorityQueue<>(
                (a, b) -> a[0] != b[0] ? Long.compare(a[0], b[0]) : Long.compare(a[1], b[1]));
        int[] cnt = new int[n];
        for (int[] m : meetings) {
            long s = m[0], e = m[1];
            while (!busy.isEmpty() && busy.peek()[0] <= s) freeRooms.offer((int) busy.poll()[1]);
            int r;
            if (!freeRooms.isEmpty()) {
                r = freeRooms.poll();
                busy.offer(new long[]{e, r});
            } else {
                long[] top = busy.poll();
                r = (int) top[1];
                busy.offer(new long[]{top[0] + e - s, r});
            }
            cnt[r]++;
        }
        int best = 0;
        for (int i = 1; i < n; i++) if (cnt[i] > cnt[best]) best = i;
        return best;
    }
}

