import (
    "container/heap"
    "sort"
)

type intHeap []int

func (h intHeap) Len() int           { return len(h) }
func (h intHeap) Less(i, j int) bool { return h[i] < h[j] }
func (h intHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *intHeap) Push(x any)        { *h = append(*h, x.(int)) }
func (h *intHeap) Pop() any {
    old := *h
    x := old[len(old)-1]
    *h = old[:len(old)-1]
    return x
}

type busyRoom struct{ end, room int }

type busyHeap []busyRoom

func (h busyHeap) Len() int { return len(h) }
func (h busyHeap) Less(i, j int) bool {
    if h[i].end != h[j].end {
        return h[i].end < h[j].end
    }
    return h[i].room < h[j].room
}
func (h busyHeap) Swap(i, j int) { h[i], h[j] = h[j], h[i] }
func (h *busyHeap) Push(x any)   { *h = append(*h, x.(busyRoom)) }
func (h *busyHeap) Pop() any {
    old := *h
    x := old[len(old)-1]
    *h = old[:len(old)-1]
    return x
}

func mostBooked(n int, meetings [][]int) int {
    sort.Slice(meetings, func(i, j int) bool { return meetings[i][0] < meetings[j][0] })
    freeRooms := &intHeap{}
    for i := 0; i < n; i++ {
        heap.Push(freeRooms, i)
    }
    busy := &busyHeap{}
    cnt := make([]int, n)
    for _, m := range meetings {
        s, e := m[0], m[1]
        for busy.Len() > 0 && (*busy)[0].end <= s {
            heap.Push(freeRooms, heap.Pop(busy).(busyRoom).room)
        }
        var r int
        if freeRooms.Len() > 0 {
            r = heap.Pop(freeRooms).(int)
            heap.Push(busy, busyRoom{e, r})
        } else {
            top := heap.Pop(busy).(busyRoom)
            r = top.room
            heap.Push(busy, busyRoom{top.end + e - s, r})
        }
        cnt[r]++
    }
    best := 0
    for i := 1; i < n; i++ {
        if cnt[i] > cnt[best] {
            best = i
        }
    }
    return best
}

