        Arrays.sort(nums);
        int n = nums.length;
        long[] pre = new long[n + 1];
        for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + nums[i];
        List<Long> res = new ArrayList<>();
        for (int qi : queries) {
            long q = qi;
            int lo = 0, hi = n; // first index with nums[idx] >= q
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (nums[mid] < q) lo = mid + 1;
                else hi = mid;
            }
            long i = lo;
            res.add(q * i - pre[lo] + (pre[n] - pre[lo]) - q * (n - i));
        }
        return res;
    }
}

