func minOperations(nums []int, queries []int) []int64 {
    sort.Ints(nums)
    n := len(nums)
    pre := make([]int, n+1)
    for i, x := range nums {
        pre[i+1] = pre[i] + x
    }
    res := make([]int64, len(queries))
    for k, q := range queries {
        i := sort.SearchInts(nums, q)
        res[k] = int64(q*i - pre[i] + (pre[n] - pre[i]) - q*(n-i))
    }
    return res
