    def generatePalindromes(self, s: str) -> List[str]:
        cnt = Counter(s)
        odd = [c for c, v in cnt.items() if v % 2]
        if len(odd) > 1:
            return []
        mid = odd[0] if odd else ''
        half = {c: v // 2 for c, v in cnt.items()}
        m = len(s) // 2
        res, path = [], []

