    string alienOrder(vector<string>& words) {
        bool present[26] = {false}, edge[26][26] = {{false}};
        int indeg[26] = {0};
        for (auto& w : words)
            for (char c : w) present[c - 'a'] = true;
        for (size_t i = 0; i + 1 < words.size(); ++i) {
            const string &a = words[i], &b = words[i + 1];
            size_t j = 0, len = min(a.size(), b.size());
            while (j < len && a[j] == b[j]) ++j;
            if (j == len) {
                if (a.size() > b.size()) return "";
                continue;
            }
            int x = a[j] - 'a', y = b[j] - 'a';
            if (!edge[x][y]) { edge[x][y] = true; ++indeg[y]; }
        }
        queue<int> q;
        int total = 0;
        for (int c = 0; c < 26; ++c) {
            if (!present[c]) continue;
            ++total;
            if (indeg[c] == 0) q.push(c);
        }
        string res;
        while (!q.empty()) {
            int c = q.front(); q.pop();
            res += char('a' + c);
            for (int d = 0; d < 26; ++d)
                if (edge[c][d] && --indeg[d] == 0) q.push(d);
        }
        return (int)res.size() == total ? res : "";
    }
