    var indeg [26]int
    for _, w := range words {
        for i := 0; i < len(w); i++ {
            present[w[i]-'a'] = true
        }
    }
    for i := 0; i+1 < len(words); i++ {
        a, b := words[i], words[i+1]
        j, n := 0, min(len(a), len(b))
        for j < n && a[j] == b[j] {
            j++
        }
        if j == n {
            if len(a) > len(b) {
                return ""
            }
            continue
        }
        x, y := a[j]-'a', b[j]-'a'
        if !edge[x][y] {
            edge[x][y] = true
            indeg[y]++
        }
    }
    var q []int
    total := 0
    for c := 0; c < 26; c++ {
        if !present[c] {
            continue
        }
        total++
        if indeg[c] == 0 {
            q = append(q, c)
        }
    }
    res := make([]byte, 0, total)
    for len(q) > 0 {
        c := q[0]
        q = q[1:]
        res = append(res, byte('a'+c))
        for d := 0; d < 26; d++ {
            if edge[c][d] {
                indeg[d]--
                if indeg[d] == 0 {
                    q = append(q, d)
                }
            }
        }
    }
    if len(res) != total {
        return ""
    }
    return string(res)
}

