class Solution {
public:
    int minExtraChar(string s, vector<string>& dictionary) {
        vector<array<int, 27>> trie(1);  // trie[v][26] == 1 marks a word end
        for (auto& w : dictionary) {
            int cur = 0;
            for (char c : w) {
                if (!trie[cur][c - 'a']) {
                    trie[cur][c - 'a'] = trie.size();
                    trie.push_back({});
                }
                cur = trie[cur][c - 'a'];
            }
            trie[cur][26] = 1;
        }
        int n = s.size();
        vector<int> dp(n + 1, 0);
        for (int i = n - 1; i >= 0; --i) {
            dp[i] = dp[i + 1] + 1;
            for (int j = i, v = 0; j < n; ++j) {
                v = trie[v][s[j] - 'a'];
                if (!v) break;
                if (trie[v][26]) dp[i] = min(dp[i], dp[j + 1]);
            }
        }
        return dp[0];
    }
};

