        path.setLength(0);
        res.clear();
        int l = 0, r = 0;
        for (char c : s.toCharArray()) {
            if (c == '(') l++;
            else if (c == ')') {
                if (l > 0) l--;
                else r++;
            }
        }
        dfs(0, l, r, 0);
        return new ArrayList<>(res);
    }

    private void dfs(int i, int l, int r, int bal) {
        if (i == s.length()) {
            if (l == 0 && r == 0 && bal == 0) res.add(path.toString());
            return;
        }
        char c = s.charAt(i);
        if (c == '(' && l > 0) dfs(i + 1, l - 1, r, bal);
        if (c == ')' && r > 0) dfs(i + 1, l, r - 1, bal);
        if (c == ')' && bal == 0) return;
        path.append(c);
        dfs(i + 1, l, r, bal + (c == '(' ? 1 : 0) - (c == ')' ? 1 : 0));
        path.setLength(path.length() - 1);
    }
