class Solution {
public:
    vector<int> findMinHeightTrees(int n, vector<vector<int>>& edges) {
        if (n == 1) return {0};
        vector<vector<int>> adj(n);
        vector<int> deg(n);
        for (auto& e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
            ++deg[e[0]], ++deg[e[1]];
        }
        vector<int> leaves;
        for (int i = 0; i < n; ++i)
            if (deg[i] == 1) leaves.push_back(i);
        int remain = n;
        while (remain > 2) {
            remain -= leaves.size();
            vector<int> nxt;
            for (int leaf : leaves) {
                deg[leaf] = 0;
                for (int nb : adj[leaf])
                    if (--deg[nb] == 1) nxt.push_back(nb);
            }
            leaves = move(nxt);
