class Solution {
    public List<Integer> findMinHeightTrees(int n, int[][] edges) {
        if (n == 1) return List.of(0);
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        int[] deg = new int[n];
        for (int[] e : edges) {
            adj.get(e[0]).add(e[1]);
            adj.get(e[1]).add(e[0]);
            deg[e[0]]++;
            deg[e[1]]++;
        }
        List<Integer> leaves = new ArrayList<>();
        for (int i = 0; i < n; i++)
            if (deg[i] == 1) leaves.add(i);
        int remain = n;
        while (remain > 2) {
            remain -= leaves.size();
            List<Integer> nxt = new ArrayList<>();
            for (int leaf : leaves) {
                deg[leaf] = 0;
                for (int nb : adj.get(leaf))
                    if (--deg[nb] == 1) nxt.add(nb);
            }
            leaves = nxt;
        }
        return leaves;
    }
}

