import random


class Solution:
    def wiggleSort(self, nums: List[int]) -> None:
        """
        Do not return anything, modify nums in-place instead.
        """
        def kth(a: List[int], k: int) -> int:  # k-th smallest, 0-based, expected O(n)
            while True:
                p = random.choice(a)
                lo = [x for x in a if x < p]
                eq = a.count(p)
                if k < len(lo):
                    a = lo
                elif k < len(lo) + eq:
                    return p
                else:
                    k -= len(lo) + eq
                    a = [x for x in a if x > p]

        n = len(nums)
        med = kth(nums, n // 2)
        idx = lambda i: (1 + 2 * i) % (n | 1)
        i, j, k = 0, 0, n - 1
        while j <= k:
            if nums[idx(j)] > med:
                nums[idx(i)], nums[idx(j)] = nums[idx(j)], nums[idx(i)]
                i += 1
                j += 1
            elif nums[idx(j)] < med:
                nums[idx(j)], nums[idx(k)] = nums[idx(k)], nums[idx(j)]
                k -= 1
            else:
                j += 1

