class Solution {
    private static final Random RND = new Random();

    public void wiggleSort(int[] nums) {
        int n = nums.length;
        int med = kth(nums, n / 2);
        int i = 0, j = 0, k = n - 1;
        while (j <= k) {
            if (nums[idx(j, n)] > med) swap(nums, idx(i++, n), idx(j++, n));
            else if (nums[idx(j, n)] < med) swap(nums, idx(j, n), idx(k--, n));
            else j++;
        }
    }

    private static int idx(int i, int n) {
        return (1 + 2 * i) % (n | 1);
    }

    // k-th smallest (0-based) via randomized quickselect with a three-way partition; expected O(n)
    private static int kth(int[] a, int k) {
        int lo = 0, hi = a.length - 1;
        while (true) {
            int p = a[lo + RND.nextInt(hi - lo + 1)];
            int lt = lo, i = lo, gt = hi;
            while (i <= gt) {
                if (a[i] < p) swap(a, lt++, i++);
                else if (a[i] > p) swap(a, i, gt--);
                else i++;
            }
            if (k < lt) hi = lt - 1;
            else if (k > gt) lo = gt + 1;
            else return p;
        }
    }

    private static void swap(int[] a, int i, int j) {
        int t = a[i];
        a[i] = a[j];
        a[j] = t;
    }
}

