import "math/rand"

// kth returns the k-th smallest (0-based) via randomized quickselect with a three-way partition; expected O(n).
func kth(a []int, k int) int {
    lo, hi := 0, len(a)-1
    for {
        p := a[lo+rand.Intn(hi-lo+1)]
        lt, i, gt := lo, lo, hi
        for i <= gt {
            if a[i] < p {
                a[lt], a[i] = a[i], a[lt]
                lt++
                i++
            } else if a[i] > p {
                a[i], a[gt] = a[gt], a[i]
                gt--
            } else {
                i++
            }
        }
        if k < lt {
            hi = lt - 1
        } else if k > gt {
            lo = gt + 1
        } else {
            return p
        }
    }
}

