class Solution:
    def longestIncreasingPath(self, matrix: List[List[int]]) -> int:
        m, n = len(matrix), len(matrix[0])

        def neighbors(i, j):
            for x, y in ((i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1)):
                if 0 <= x < m and 0 <= y < n:
                    yield x, y

        out = [[sum(matrix[x][y] > matrix[i][j] for x, y in neighbors(i, j)) for j in range(n)] for i in range(m)]
        layer = [(i, j) for i in range(m) for j in range(n) if out[i][j] == 0]
        depth = 0
        while layer:
            depth += 1
            nxt = []
            for i, j in layer:
                for x, y in neighbors(i, j):
                    if matrix[x][y] < matrix[i][j]:
                        out[x][y] -= 1
                        if out[x][y] == 0:
                            nxt.append((x, y))
            layer = nxt
        return depth

