class Solution {
    pair<int, int> dfs(TreeNode* node) {  // {robbed, skipped}
        if (!node) return {0, 0};
        auto [lr, ls] = dfs(node->left);
        auto [rr, rs] = dfs(node->right);
        return {node->val + ls + rs, max(lr, ls) + max(rr, rs)};
    }

