class Solution:
    def solveSudoku(self, board: List[List[str]]) -> None:
        """
        Do not return anything, modify board in-place instead.
        """
        rows, cols, boxes = [0] * 9, [0] * 9, [0] * 9
        empty = []

        def toggle(r, c, bit):
            rows[r] ^= bit
            cols[c] ^= bit
            boxes[r // 3 * 3 + c // 3] ^= bit

        for r in range(9):
            for c in range(9):
                if board[r][c] == '.':
                    empty.append((r, c))
                else:
                    toggle(r, c, 1 << (int(board[r][c]) - 1))

        def dfs(k):
            if k == len(empty):
                return True
            r, c = empty[k]
            free = ~(rows[r] | cols[c] | boxes[r // 3 * 3 + c // 3]) & 0x1FF
            while free:
                bit = free & -free
                free ^= bit
                toggle(r, c, bit)
                board[r][c] = str(bit.bit_length())
                if dfs(k + 1):
                    return True
                toggle(r, c, bit)
            board[r][c] = '.'
            return False

        dfs(0)

