    public List<List<Integer>> kSmallestPairs(int[] nums1, int[] nums2, int k) {
        // entries are {i, j}; order by pair sum, ties by i
        PriorityQueue<int[]> pq = new PriorityQueue<>((p, q) -> {
            int c = Long.compare((long) nums1[p[0]] + nums2[p[1]], (long) nums1[q[0]] + nums2[q[1]]);
            return c != 0 ? c : Integer.compare(p[0], q[0]);
        });
        for (int i = 0; i < Math.min(k, nums1.length); i++) pq.offer(new int[]{i, 0});
        List<List<Integer>> res = new ArrayList<>();
        while (!pq.isEmpty() && res.size() < k) {
            int[] top = pq.poll();
            int i = top[0], j = top[1];
            res.add(List.of(nums1[i], nums2[j]));
            if (j + 1 < nums2.length) pq.offer(new int[]{i, j + 1});
        }
        return res;
    }
