import "container/heap"

type pairHeap [][3]int // (sum, i, j)

func (h pairHeap) Len() int { return len(h) }
func (h pairHeap) Less(a, b int) bool {
    if h[a][0] != h[b][0] {
        return h[a][0] < h[b][0]
    }
    return h[a][1] < h[b][1]
}
func (h pairHeap) Swap(a, b int) { h[a], h[b] = h[b], h[a] }
func (h *pairHeap) Push(x any)   { *h = append(*h, x.([3]int)) }
func (h *pairHeap) Pop() any {
    old := *h
    x := old[len(old)-1]
    *h = old[:len(old)-1]
    return x
}

func kSmallestPairs(nums1 []int, nums2 []int, k int) [][]int {
    h := &pairHeap{}
    for i := 0; i < min(k, len(nums1)); i++ {
        heap.Push(h, [3]int{nums1[i] + nums2[0], i, 0})
    }
    res := [][]int{}
    for h.Len() > 0 && len(res) < k {
        top := heap.Pop(h).([3]int)
        i, j := top[1], top[2]
        res = append(res, []int{nums1[i], nums2[j]})
        if j+1 < len(nums2) {
            heap.Push(h, [3]int{nums1[i] + nums2[j+1], i, j + 1})
        }
    }
    return res
}

