        for (char ch : s.toCharArray()) {
            if (Character.isDigit(ch)) {
                num = num * 10 + (ch - '0');
            } else if (ch == '[') {
                prevs.push(cur.toString());
                counts.push(num);
                cur.setLength(0);
                num = 0;
            } else if (ch == ']') {
                String rep = cur.toString().repeat(counts.pop());
                cur = new StringBuilder(prevs.pop()).append(rep);
            } else {
                cur.append(ch);
            }
        }
        return cur.toString();
