import "strings"

func decodeString(s string) string {
    type frame struct {
        prev string
        k    int
    }
    var stack []frame
    cur, num := "", 0
    for i := 0; i < len(s); i++ {
        ch := s[i]
        switch {
        case ch >= '0' && ch <= '9':
            num = num*10 + int(ch-'0')
        case ch == '[':
            stack = append(stack, frame{cur, num})
            cur, num = "", 0
        case ch == ']':
            top := stack[len(stack)-1]
            stack = stack[:len(stack)-1]
            cur = top.prev + strings.Repeat(cur, top.k)
        default:
            cur += string(ch)
        }
    }
    return cur
}

