        parent, ratio = {}, {}  # ratio[x] = x / parent[x]

        def find(x):
            if parent[x] != x:
                p = parent[x]
                root = find(p)
                ratio[x] *= ratio[p]
                parent[x] = root
            return parent[x]

        for (a, b), v in zip(equations, values):
            for x in (a, b):
                if x not in parent:
                    parent[x], ratio[x] = x, 1.0
            ra, rb = find(a), find(b)
            if ra != rb:
                parent[ra] = rb
                ratio[ra] = v * ratio[b] / ratio[a]

        res = []
        for a, b in queries:
            if a not in parent or b not in parent or find(a) != find(b):
                res.append(-1.0)
            else:
                res.append(ratio[a] / ratio[b])
        return res

