class Solution {
    private final Map<String, String> parent = new HashMap<>();
    private final Map<String, Double> ratio = new HashMap<>(); // ratio[x] = x / parent[x]

    public double[] calcEquation(List<List<String>> equations, double[] values, List<List<String>> queries) {
        parent.clear();
        ratio.clear();
        for (int i = 0; i < equations.size(); i++) {
            String a = equations.get(i).get(0), b = equations.get(i).get(1);
            for (String x : List.of(a, b))
                if (!parent.containsKey(x)) {
                    parent.put(x, x);
                    ratio.put(x, 1.0);
                }
            String ra = find(a), rb = find(b);
            if (!ra.equals(rb)) {
                parent.put(ra, rb);
                ratio.put(ra, values[i] * ratio.get(b) / ratio.get(a));
            }
        }
        double[] res = new double[queries.size()];
        for (int i = 0; i < queries.size(); i++) {
            String a = queries.get(i).get(0), b = queries.get(i).get(1);
            if (!parent.containsKey(a) || !parent.containsKey(b) || !find(a).equals(find(b))) res[i] = -1.0;
            else res[i] = ratio.get(a) / ratio.get(b);
        }
        return res;
    }

