func calcEquation(equations [][]string, values []float64, queries [][]string) []float64 {
    parent := map[string]string{}
    ratio := map[string]float64{} // ratio[x] = x / parent[x]
    var find func(x string) string
    find = func(x string) string {
        if p := parent[x]; p != x {
            root := find(p)
            ratio[x] *= ratio[p]
            parent[x] = root
        }
        return parent[x]
    }
    for i, e := range equations {
        a, b := e[0], e[1]
        for _, x := range []string{a, b} {
            if _, ok := parent[x]; !ok {
                parent[x], ratio[x] = x, 1.0
            }
        }
        ra, rb := find(a), find(b)
        if ra != rb {
            parent[ra] = rb
            ratio[ra] = values[i] * ratio[b] / ratio[a]
        }
    }
    res := make([]float64, len(queries))
    for i, q := range queries {
        _, okA := parent[q[0]]
        _, okB := parent[q[1]]
        if !okA || !okB || find(q[0]) != find(q[1]) {
            res[i] = -1.0
        } else {
            res[i] = ratio[q[0]] / ratio[q[1]]
        }
    }
    return res
}

