class Solution {
public:
    vector<vector<int>> pacificAtlantic(vector<vector<int>>& heights) {
        int m = heights.size(), n = heights[0].size();
        auto climb = [&](vector<pair<int, int>> starts) {
            vector<vector<char>> seen(m, vector<char>(n, 0));
            for (auto [r, c] : starts) seen[r][c] = 1;
            int dr[4] = {1, -1, 0, 0}, dc[4] = {0, 0, 1, -1};
            while (!starts.empty()) {
                auto [r, c] = starts.back();
                starts.pop_back();
                for (int d = 0; d < 4; ++d) {
                    int nr = r + dr[d], nc = c + dc[d];
                    if (nr < 0 || nr >= m || nc < 0 || nc >= n || seen[nr][nc]) continue;
                    if (heights[nr][nc] < heights[r][c]) continue;
                    seen[nr][nc] = 1;
                    starts.push_back({nr, nc});
                }
            }
            return seen;
        };
        vector<pair<int, int>> p, a;
        for (int c = 0; c < n; ++c) p.push_back({0, c}), a.push_back({m - 1, c});
        for (int r = 0; r < m; ++r) p.push_back({r, 0}), a.push_back({r, n - 1});
        auto pac = climb(p), atl = climb(a);
        vector<vector<int>> res;
        for (int r = 0; r < m; ++r)
            for (int c = 0; c < n; ++c)
                if (pac[r][c] && atl[r][c]) res.push_back({r, c});
        return res;
    }
};

