        m = heights.length;
        n = heights[0].length;
        List<int[]> pacStarts = new ArrayList<>(), atlStarts = new ArrayList<>();
        for (int c = 0; c < n; c++) {
            pacStarts.add(new int[]{0, c});
            atlStarts.add(new int[]{m - 1, c});
        }
        for (int r = 0; r < m; r++) {
            pacStarts.add(new int[]{r, 0});
            atlStarts.add(new int[]{r, n - 1});
        }
        boolean[][] pac = climb(pacStarts), atl = climb(atlStarts);
        List<List<Integer>> res = new ArrayList<>();
        for (int r = 0; r < m; r++)
            for (int c = 0; c < n; c++)
                if (pac[r][c] && atl[r][c]) res.add(List.of(r, c));
        return res;
    }

    private boolean[][] climb(List<int[]> starts) {
        boolean[][] seen = new boolean[m][n];
        Deque<int[]> stack = new ArrayDeque<>();
        for (int[] p : starts) {
            if (!seen[p[0]][p[1]]) {
                seen[p[0]][p[1]] = true;
                stack.push(p);
            }
        }
        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        while (!stack.isEmpty()) {
            int[] p = stack.pop();
            int r = p[0], c = p[1];
            for (int[] d : dirs) {
                int nr = r + d[0], nc = c + d[1];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n && !seen[nr][nc]
                        && heights[nr][nc] >= heights[r][c]) {
                    seen[nr][nc] = true;
                    stack.push(new int[]{nr, nc});
                }
            }
        }
        return seen;
    }
}

