    private final Bucket head = new Bucket(0), tail = new Bucket(0);
    private final Map<String, Bucket> where = new HashMap<>();

    public AllOne() {
        head.next = tail;
        tail.prev = head;
    }

    private Bucket addAfter(Bucket node, int cnt) {
        Bucket b = new Bucket(cnt);
        b.prev = node;
        b.next = node.next;
        node.next.prev = b;
        node.next = b;
        return b;
    }

    private void dropKey(Bucket b, String key) {
        b.keys.remove(key);
        if (b.keys.isEmpty()) {
            b.prev.next = b.next;
            b.next.prev = b.prev;
        }
    }

