type bucket struct {
    cnt        int
    keys       map[string]struct{}
    prev, next *bucket
}

type AllOne struct {
    head, tail *bucket // sentinels, count 0 never matches a real bucket
    where      map[string]*bucket
}

func Constructor() AllOne {
    head, tail := &bucket{}, &bucket{}
    head.next, tail.prev = tail, head
    return AllOne{head: head, tail: tail, where: map[string]*bucket{}}
}

func (this *AllOne) addAfter(node *bucket, cnt int) *bucket {
    b := &bucket{cnt: cnt, keys: map[string]struct{}{}, prev: node, next: node.next}
    node.next.prev = b
    node.next = b
    return b
}

func (this *AllOne) dropKey(b *bucket, key string) {
    delete(b.keys, key)
    if len(b.keys) == 0 {
        b.prev.next, b.next.prev = b.next, b.prev
    }
}

func (this *AllOne) Inc(key string) {
    cur, ok := this.where[key]
    if !ok {
        cur = this.head
    }
    nxt := cur.next
    if nxt.cnt != cur.cnt+1 {
        nxt = this.addAfter(cur, cur.cnt+1)
    }
    nxt.keys[key] = struct{}{}
    this.where[key] = nxt
    if cur != this.head {
        this.dropKey(cur, key)
    }
}

func (this *AllOne) Dec(key string) {
    cur := this.where[key]
    delete(this.where, key)
    if cur.cnt > 1 {
        prv := cur.prev
        if prv.cnt != cur.cnt-1 {
            prv = this.addAfter(prv, cur.cnt-1)
        }
        prv.keys[key] = struct{}{}
        this.where[key] = prv
    }
    this.dropKey(cur, key)
}

func (this *AllOne) GetMaxKey() string {
    if b := this.tail.prev; b != this.head {
        for k := range b.keys {
            return k
        }
    }
    return ""
}

func (this *AllOne) GetMinKey() string {
    if b := this.head.next; b != this.tail {
        for k := range b.keys {
            return k
        }
    }
    return ""
}

