        for (; l2; l2 = l2->next) b.push_back(l2->val);
        ListNode* head = nullptr;
        int carry = 0;
        while (!a.empty() || !b.empty() || carry) {
            if (!a.empty()) carry += a.back(), a.pop_back();
            if (!b.empty()) carry += b.back(), b.pop_back();
            head = new ListNode(carry % 10, head);
            carry /= 10;
        }
        return head;
    }
};

