        function<void(TreeNode*)> pre = [&](TreeNode* node) {
            if (!node) return;
            out += to_string(node->val) + ' ';
            pre(node->left);
            pre(node->right);
        };
        pre(root);
        return out;
    }

    // Decodes your encoded data to tree.
    TreeNode* deserialize(string data) {
        vector<int> vals;
        istringstream in(data);
        for (int x; in >> x;) vals.push_back(x);
        size_t i = 0;
        function<TreeNode*(long long, long long)> build = [&](long long lo, long long hi) -> TreeNode* {
            if (i == vals.size() || vals[i] <= lo || vals[i] >= hi) return nullptr;
            TreeNode* node = new TreeNode(vals[i++]);
            node->left = build(lo, node->val);
            node->right = build(node->val, hi);
            return node;
        };
        return build(LLONG_MIN, LLONG_MAX);
    }
};

