        if node != nil {
            out = append(out, strconv.Itoa(node.Val))
            pre(node.Left)
            pre(node.Right)
        }
    }
    pre(root)
    return strings.Join(out, " ")
}

func (this *Codec) deserialize(data string) *TreeNode {
    fields := strings.Fields(data)
    vals := make([]int, len(fields))
    for k, f := range fields {
        vals[k], _ = strconv.Atoi(f)
    }
    i := 0
    var build func(lo, hi int) *TreeNode
    build = func(lo, hi int) *TreeNode {
        if i == len(vals) || !(lo < vals[i] && vals[i] < hi) {
            return nil
        }
        node := &TreeNode{Val: vals[i]}
        i++
        node.Left = build(lo, node.Val)
        node.Right = build(node.Val, hi)
        return node
    }
    return build(math.MinInt, math.MaxInt)
}

