class LFUCache:

    def __init__(self, capacity: int):
        self.cap = capacity
        self.node = {}                        # key -> [value, freq]
        self.bucket = defaultdict(OrderedDict)  # freq -> keys, oldest first
        self.min_freq = 0

    def _touch(self, key: int) -> None:
