        del self.bucket[f][key]
        if not self.bucket[f]:
            del self.bucket[f]
            if self.min_freq == f:
                self.min_freq += 1
        self.node[key][1] = f + 1
        self.bucket[f + 1][key] = None

    def get(self, key: int) -> int:
        if key not in self.node:
            return -1
        self._touch(key)
        return self.node[key][0]

    def put(self, key: int, value: int) -> None:
        if self.cap == 0:
            return
        if key in self.node:
            self.node[key][0] = value
            self._touch(key)
            return
        if len(self.node) == self.cap:
            old, _ = self.bucket[self.min_freq].popitem(last=False)
            if not self.bucket[self.min_freq]:
                del self.bucket[self.min_freq]
            del self.node[old]
        self.node[key] = [value, 1]
        self.bucket[1][key] = None
