class LFUCache {
    struct Entry { int value, freq; list<int>::iterator it; };
    int cap, minFreq = 0;
    unordered_map<int, Entry> node;          // key -> value, freq, position in its bucket
    unordered_map<int, list<int>> bucket;    // freq -> keys, oldest at front

    void touch(Entry& e, int key) {
        auto& b = bucket[e.freq];
        b.erase(e.it);
        if (b.empty()) {
            bucket.erase(e.freq);
            if (minFreq == e.freq) ++minFreq;
        }
        ++e.freq;
        auto& nb = bucket[e.freq];
        e.it = nb.insert(nb.end(), key);
    }

public:
    LFUCache(int capacity) : cap(capacity) {}

    int get(int key) {
        auto f = node.find(key);
        if (f == node.end()) return -1;
        touch(f->second, key);
        return f->second.value;
    }

    void put(int key, int value) {
        if (cap == 0) return;
        auto f = node.find(key);
        if (f != node.end()) {
            f->second.value = value;
            touch(f->second, key);
            return;
        }
        if ((int)node.size() == cap) {
            auto& b = bucket[minFreq];
            node.erase(b.front());
            b.pop_front();
            if (b.empty()) bucket.erase(minFreq);
        }
        auto& b1 = bucket[1];
        node[key] = {value, 1, b1.insert(b1.end(), key)};
        minFreq = 1;
    }
