class LFUCache {
    private final int cap;
    private final Map<Integer, int[]> node = new HashMap<>(); // key -> {value, freq}
    private final Map<Integer, LinkedHashSet<Integer>> bucket = new HashMap<>(); // freq -> keys, oldest first
    private int minFreq = 0;

    public LFUCache(int capacity) {
        cap = capacity;
    }

    private void touch(int key) {
        int[] e = node.get(key);
        int f = e[1];
        LinkedHashSet<Integer> keys = bucket.get(f);
        keys.remove(key);
        if (keys.isEmpty()) {
            bucket.remove(f);
            if (minFreq == f) minFreq++;
        }
        e[1] = f + 1;
        bucket.computeIfAbsent(f + 1, x -> new LinkedHashSet<>()).add(key);
    }

    public int get(int key) {
        if (!node.containsKey(key)) return -1;
        touch(key);
        return node.get(key)[0];
    }

    public void put(int key, int value) {
        if (cap == 0) return;
        if (node.containsKey(key)) {
            node.get(key)[0] = value;
            touch(key);
            return;
        }
        if (node.size() == cap) {
            LinkedHashSet<Integer> keys = bucket.get(minFreq);
            int old = keys.iterator().next();
            keys.remove(old);
            if (keys.isEmpty()) bucket.remove(minFreq);
            node.remove(old);
        }
        node.put(key, new int[]{value, 1});
        bucket.computeIfAbsent(1, x -> new LinkedHashSet<>()).add(key);
        minFreq = 1;
    }
