import "container/list"

type lfuEntry struct {
    val, freq int
    elem      *list.Element
}

type LFUCache struct {
    cap     int
    node    map[int]*lfuEntry
    bucket  map[int]*list.List // freq -> keys, oldest at the front
    minFreq int
}

func Constructor(capacity int) LFUCache {
    return LFUCache{cap: capacity, node: map[int]*lfuEntry{}, bucket: map[int]*list.List{}}
}

func (this *LFUCache) push(freq, key int) *list.Element {
    l, ok := this.bucket[freq]
    if !ok {
        l = list.New()
        this.bucket[freq] = l
    }
    return l.PushBack(key)
}

func (this *LFUCache) touch(e *lfuEntry) {
    f := e.freq
    l := this.bucket[f]
    key := l.Remove(e.elem).(int)
    if l.Len() == 0 {
        delete(this.bucket, f)
        if this.minFreq == f {
            this.minFreq++
        }
    }
    e.freq = f + 1
    e.elem = this.push(f+1, key)
}

func (this *LFUCache) Get(key int) int {
    e, ok := this.node[key]
    if !ok {
        return -1
    }
    this.touch(e)
    return e.val
}

func (this *LFUCache) Put(key int, value int) {
    if this.cap == 0 {
        return
    }
    if e, ok := this.node[key]; ok {
        e.val = value
        this.touch(e)
        return
    }
    if len(this.node) == this.cap {
        l := this.bucket[this.minFreq]
        old := l.Remove(l.Front()).(int)
        if l.Len() == 0 {
            delete(this.bucket, this.minFreq)
        }
        delete(this.node, old)
    }
    this.node[key] = &lfuEntry{val: value, freq: 1, elem: this.push(1, key)}
    this.minFreq = 1
}

