    int islandPerimeter(vector<vector<int>>& grid) {
        int res = 0;
        for (size_t i = 0; i < grid.size(); ++i)
            for (size_t j = 0; j < grid[i].size(); ++j) {
                if (!grid[i][j]) continue;
                res += 4;
                if (i && grid[i - 1][j]) res -= 2;
                if (j && grid[i][j - 1]) res -= 2;
            }
        return res;
    }
};

