        vector<bool> used(nums.size(), false);
        function<void()> dfs = [&]() {
            if (path.size() == nums.size()) { res.push_back(path); return; }
            for (size_t i = 0; i < nums.size(); ++i) {
                if (used[i] || (i && nums[i] == nums[i - 1] && !used[i - 1])) continue;
                used[i] = true;
                path.push_back(nums[i]);
                dfs();
                path.pop_back();
                used[i] = false;
            }
        };
        dfs();
        return res;
    }
