            res = append(res, append([]int(nil), path...))
            return
        }
        for i, x := range nums {
            if used[i] || (i > 0 && x == nums[i-1] && !used[i-1]) {
                continue
            }
            used[i] = true
            path = append(path, x)
            dfs()
            path = path[:len(path)-1]
            used[i] = false
        }
    }
    dfs()
    return res
}

