class Solution:
    def hasPath(self, maze: List[List[int]], start: List[int], destination: List[int]) -> bool:
        m, n = len(maze), len(maze[0])
        seen = {tuple(start)}
        q = deque([tuple(start)])
        while q:
            r, c = q.popleft()
            if [r, c] == destination:
                return True
            for dr, dc in (1, 0), (-1, 0), (0, 1), (0, -1):
                x, y = r, c
                while 0 <= x + dr < m and 0 <= y + dc < n and maze[x + dr][y + dc] == 0:
                    x, y = x + dr, y + dc
                if (x, y) not in seen:
                    seen.add((x, y))
                    q.append((x, y))
        return False

