class Solution {
public:
    int findTargetSumWays(vector<int>& nums, int target) {
        int n = nums.size(), total = accumulate(nums.begin(), nums.end(), 0);
        vector<vector<int>> memo(n, vector<int>(2 * total + 1, -1));
        function<int(int, int)> dfs = [&](int i, int cur) -> int {
            if (i == n) return cur == target;
            int& r = memo[i][cur + total];
            if (r != -1) return r;
            return r = dfs(i + 1, cur + nums[i]) + dfs(i + 1, cur - nums[i]);
        };
        return dfs(0, 0);
    }
};

