class Solution {
    private int[] nums;
    private int target, offset;
    private Integer[][] memo;

    public int findTargetSumWays(int[] nums, int target) {
        this.nums = nums;
        this.target = target;
        for (int x : nums) offset += x;
        memo = new Integer[nums.length][2 * offset + 1];
        return dfs(0, 0);
    }

    private int dfs(int i, int cur) {
        if (i == nums.length) return cur == target ? 1 : 0;
        if (memo[i][cur + offset] == null)
            memo[i][cur + offset] = dfs(i + 1, cur + nums[i]) + dfs(i + 1, cur - nums[i]);
        return memo[i][cur + offset];
    }
}

