func findTargetSumWays(nums []int, target int) int {
    type state struct{ i, cur int }
    memo := map[state]int{}
    var dfs func(i, cur int) int
    dfs = func(i, cur int) int {
        if i == len(nums) {
            if cur == target {
                return 1
            }
            return 0
        }
        key := state{i, cur}
        if v, ok := memo[key]; ok {
            return v
        }
        v := dfs(i+1, cur+nums[i]) + dfs(i+1, cur-nums[i])
        memo[key] = v
        return v
    }
    return dfs(0, 0)
}

