class Solution:
    def longestPalindrome(self, s: str) -> str:
        n = len(s)

        def expand(l, r):
            while l >= 0 and r < n and s[l] == s[r]:
                l -= 1
                r += 1
            return l + 1, r  # palindrome is s[l+1:r]

        lo, hi = 0, 1
        for i in range(n):
            for l, r in (expand(i, i), expand(i, i + 1)):
                if r - l > hi - lo:
                    lo, hi = l, r
        return s[lo:hi]

