import (
    "container/heap"
    "sort"
)

type maxHeap struct{ sort.IntSlice }

func (h maxHeap) Less(i, j int) bool { return h.IntSlice[i] > h.IntSlice[j] }
func (h *maxHeap) Push(x any)        { h.IntSlice = append(h.IntSlice, x.(int)) }
func (h *maxHeap) Pop() any {
    a := h.IntSlice
    v := a[len(a)-1]
    h.IntSlice = a[:len(a)-1]
    return v
}

func findMaximizedCapital(k int, w int, profits []int, capital []int) int {
    n := len(profits)
    order := make([]int, n)
    for i := range order {
        order[i] = i
    }
    sort.Slice(order, func(a, b int) bool { return capital[order[a]] < capital[order[b]] })
    h := &maxHeap{}
    i := 0
    for ; k > 0; k-- {
        for i < n && capital[order[i]] <= w {
            heap.Push(h, profits[order[i]])
            i++
        }
        if h.Len() == 0 {
            break
        }
        w += heap.Pop(h).(int)
    }
    return w
}

