import (
    "container/heap"
    "math"
)

type distHeap [][3]int // {dist, row, col}

func (h distHeap) Len() int           { return len(h) }
func (h distHeap) Less(i, j int) bool { return h[i][0] < h[j][0] }
func (h distHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *distHeap) Push(x any)        { *h = append(*h, x.([3]int)) }
func (h *distHeap) Pop() any {
    old := *h
    v := old[len(old)-1]
    *h = old[:len(old)-1]
    return v
}

func shortestDistance(maze [][]int, start []int, destination []int) int {
    m, n := len(maze), len(maze[0])
    dist := make([][]int, m)
    for i := range dist {
        dist[i] = make([]int, n)
        for j := range dist[i] {
            dist[i][j] = math.MaxInt
        }
    }
    dist[start[0]][start[1]] = 0
    pq := &distHeap{{0, start[0], start[1]}}
    dirs := [][2]int{{1, 0}, {-1, 0}, {0, 1}, {0, -1}}
    for pq.Len() > 0 {
        top := heap.Pop(pq).([3]int)
        d, r, c := top[0], top[1], top[2]
        if d > dist[r][c] {
            continue
        }
        if r == destination[0] && c == destination[1] {
            return d
        }
        for _, dir := range dirs {
            x, y, steps := r, c, 0
            for x+dir[0] >= 0 && x+dir[0] < m && y+dir[1] >= 0 && y+dir[1] < n && maze[x+dir[0]][y+dir[1]] == 0 {
                x, y, steps = x+dir[0], y+dir[1], steps+1
            }
            if d+steps < dist[x][y] {
                dist[x][y] = d + steps
                heap.Push(pq, [3]int{d + steps, x, y})
            }
        }
    }
    return -1
}

