    var dfs func(r int)
    dfs = func(r int) {
        if r == n {
            board := make([]string, n)
            for i, c := range pos {
                board[i] = strings.Repeat(".", c) + "Q" + strings.Repeat(".", n-c-1)
            }
            res = append(res, board)
            return
        }
        for c := 0; c < n; c++ {
            if col[c] || d1[r-c+n] || d2[r+c] {
                continue
            }
            pos[r] = c
            col[c], d1[r-c+n], d2[r+c] = true, true, true
            dfs(r + 1)
            col[c], d1[r-c+n], d2[r+c] = false, false, false
        }
    }
    dfs(0)
    return res
}

