class Solution:
    def totalNQueens(self, n: int) -> int:
        full = (1 << n) - 1

        def dfs(cols, d1, d2):
            if cols == full:
                return 1
            cnt, free = 0, full & ~(cols | d1 | d2)
            while free:
                bit = free & -free
