class Solution:
    def boundaryOfBinaryTree(self, root: Optional[TreeNode]) -> List[int]:
        def leaf(n):
            return not n.left and not n.right

        res = [root.val]
        if leaf(root):
            return res
        node = root.left
        while node and not leaf(node):
            res.append(node.val)
            node = node.left or node.right
        stack = [root.right, root.left]
        while stack:
            node = stack.pop()
            if not node:
                continue
            if leaf(node):
                res.append(node.val)
            else:
                stack += [node.right, node.left]
        right = []
        node = root.right
        while node and not leaf(node):
            right.append(node.val)
            node = node.right or node.left
        return res + right[::-1]

