 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
    static bool leaf(TreeNode* n) { return !n->left && !n->right; }
    void leaves(TreeNode* n, vector<int>& out) {
        if (!n) return;
        if (leaf(n)) { out.push_back(n->val); return; }
        leaves(n->left, out);
        leaves(n->right, out);
    }
public:
    vector<int> boundaryOfBinaryTree(TreeNode* root) {
        vector<int> res{root->val};
        if (leaf(root)) return res;
        for (TreeNode* n = root->left; n && !leaf(n); n = n->left ? n->left : n->right)
            res.push_back(n->val);
        leaves(root->left, res);
        leaves(root->right, res);
        vector<int> right;
        for (TreeNode* n = root->right; n && !leaf(n); n = n->right ? n->right : n->left)
            right.push_back(n->val);
        res.insert(res.end(), right.rbegin(), right.rend());
        return res;
    }
};

