class Solution {
    public List<Integer> boundaryOfBinaryTree(TreeNode root) {
        List<Integer> res = new ArrayList<>();
        res.add(root.val);
        if (isLeaf(root)) return res;
        for (TreeNode n = root.left; n != null && !isLeaf(n); n = n.left != null ? n.left : n.right)
            res.add(n.val);
        leaves(root.left, res);
        leaves(root.right, res);
        List<Integer> right = new ArrayList<>();
        for (TreeNode n = root.right; n != null && !isLeaf(n); n = n.right != null ? n.right : n.left)
            right.add(n.val);
        Collections.reverse(right);
        res.addAll(right);
        return res;
    }

    private boolean isLeaf(TreeNode n) {
        return n.left == null && n.right == null;
    }

    private void leaves(TreeNode n, List<Integer> out) {
        if (n == null) return;
        if (isLeaf(n)) {
            out.add(n.val);
            return;
        }
        leaves(n.left, out);
        leaves(n.right, out);
    }
}

