class Solution {
    void ser(TreeNode* n, string& out) {
        if (!n) { out += "#,"; return; }
        out += to_string(n->val) + ',';
        ser(n->left, out);
        ser(n->right, out);
    }
public:
    bool isSubtree(TreeNode* root, TreeNode* subRoot) {
        string s = ",", t = ",";
        ser(root, s);
        ser(subRoot, t);
        string p = t + '|' + s;  // KMP prefix function over pattern|text
        vector<int> pi(p.size());
        for (size_t i = 1; i < p.size(); ++i) {
            int k = pi[i - 1];
            while (k && p[i] != p[k]) k = pi[k - 1];
            if (p[i] == p[k]) ++k;
            pi[i] = k;
            if (k == (int)t.size()) return true;
        }
        return false;
    }
};

