    "strings"
)

type dirNode struct {
    kids    map[string]*dirNode
    isFile  bool
    content string
}

type FileSystem struct {
    root *dirNode
}

func Constructor() FileSystem {
    return FileSystem{root: &dirNode{kids: map[string]*dirNode{}}}
}

func (this *FileSystem) walk(path string) *dirNode {
    cur := this.root
    for _, part := range strings.Split(path, "/") {
        if part == "" {
            continue
        }
        next, ok := cur.kids[part]
        if !ok {
            next = &dirNode{kids: map[string]*dirNode{}}
            cur.kids[part] = next
        }
        cur = next
    }
    return cur
}

func (this *FileSystem) Ls(path string) []string {
    node := this.walk(path)
    if node.isFile {
        return []string{path[strings.LastIndexByte(path, '/')+1:]}
    }
    res := make([]string, 0, len(node.kids))
    for name := range node.kids {
        res = append(res, name)
    }
    sort.Strings(res)
    return res
}

func (this *FileSystem) Mkdir(path string) {
    this.walk(path)
}

func (this *FileSystem) AddContentToFile(filePath string, content string) {
    node := this.walk(filePath)
    node.isFile = true
    node.content += content
}

func (this *FileSystem) ReadContentFromFile(filePath string) string {
    return this.walk(filePath).content
}

