class Solution:
    def leastInterval(self, tasks: List[str], n: int) -> int:
        heap = [-c for c in Counter(tasks).values()]
        heapq.heapify(heap)
        time = 0
        while heap:
            left, k = [], 0
            while k <= n and heap:
                c = heapq.heappop(heap) + 1
                if c:
                    left.append(c)
                k += 1
            for c in left:
                heapq.heappush(heap, c)
            time += n + 1 if heap else k
        return time

