class Solution {
public:
    int leastInterval(vector<char>& tasks, int n) {
        int cnt[26] = {};
        for (char c : tasks) ++cnt[c - 'A'];
        priority_queue<int> pq;
        for (int c : cnt) if (c) pq.push(c);
        int time = 0;
        while (!pq.empty()) {
            vector<int> left;
            int k = 0;
            for (; k <= n && !pq.empty(); ++k) {
                int c = pq.top(); pq.pop();
                if (c > 1) left.push_back(c - 1);
            }
            for (int c : left) pq.push(c);
            time += pq.empty() ? k : n + 1;
        }
        return time;
    }
};

