func leastInterval(tasks []byte, n int) int {
    var cnt [26]int
    for _, c := range tasks {
        cnt[c-'A']++
    }
    h := &maxHeap{}
    for _, c := range cnt {
        if c > 0 {
            *h = append(*h, c)
        }
    }
    heap.Init(h)
    time := 0
    for h.Len() > 0 {
        var left []int
        k := 0
        for ; k <= n && h.Len() > 0; k++ {
            if c := heap.Pop(h).(int); c > 1 {
                left = append(left, c-1)
            }
        }
        for _, c := range left {
            heap.Push(h, c)
        }
        if h.Len() == 0 {
            time += k
        } else {
            time += n + 1
        }
    }
    return time
}

