            int[] top = pq.poll();
            int lo = top[0], i = top[1], j = top[2];
            if (hi - lo < best[1] - best[0]) best = new int[]{lo, hi};
            if (j + 1 == nums.get(i).size()) return best;
            int v = nums.get(i).get(j + 1);
            hi = Math.max(hi, v);
            pq.add(new int[]{v, i, j + 1});
        }
    }
