/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
    int widthOfBinaryTree(TreeNode* root) {
        using P = pair<TreeNode*, unsigned long long>;
        vector<P> level = {{root, 0}};
        unsigned long long ans = 0;
        while (!level.empty()) {
            ans = max(ans, level.back().second - level.front().second + 1);
            unsigned long long base = level.front().second;
            vector<P> nxt;
            for (auto [node, i] : level) {
                i -= base;
                if (node->left) nxt.push_back({node->left, 2 * i});
                if (node->right) nxt.push_back({node->right, 2 * i + 1});
            }
            level = std::move(nxt);
        }
        return ans;
    }
};

