        while (!level.isEmpty()) {
            long base = idx.get(0);
            ans = Math.max(ans, idx.get(idx.size() - 1) - base + 1);
            List<TreeNode> nextLevel = new ArrayList<>();
            List<Long> nextIdx = new ArrayList<>();
            for (int k = 0; k < level.size(); k++) {
                TreeNode node = level.get(k);
                long i = idx.get(k) - base; // re-base to keep indices small
                if (node.left != null) {
                    nextLevel.add(node.left);
                    nextIdx.add(2 * i);
                }
                if (node.right != null) {
                    nextLevel.add(node.right);
                    nextIdx.add(2 * i + 1);
                }
            }
            level = nextLevel;
            idx = nextIdx;
        }
        return (int) ans;
    }
}

