            if len(a) == 1:
                return abs(a[0] - 24) < 1e-6
            for i in range(len(a)):
                for j in range(len(a)):
                    if i == j:
                        continue
                    rest = [a[k] for k in range(len(a)) if k != i and k != j]
                    x, y = a[i], a[j]
                    cand = [x + y, x - y, x * y]
                    if abs(y) > 1e-6:
                        cand.append(x / y)
                    if any(dfs(rest + [v]) for v in cand):
                        return True
            return False

