class Solution:
    def fullJustify(self, words: List[str], maxWidth: int) -> List[str]:
        res, i, n = [], 0, len(words)
        while i < n:
            j, width = i, 0
            while j < n and width + len(words[j]) + (j - i) <= maxWidth:
                width += len(words[j])
                j += 1
            gaps = j - i - 1
            if j == n or gaps == 0:
                line = ' '.join(words[i:j]).ljust(maxWidth)
            else:
                q, r = divmod(maxWidth - width, gaps)
                line = ''.join(words[k] + ' ' * (q + (k - i < r)) for k in range(i, j - 1)) + words[j - 1]
            res.append(line)
            i = j
        return res

