class Solution:
    def minStickers(self, stickers: List[str], target: str) -> int:
        n = len(target)
        full = (1 << n) - 1
        t = [ord(ch) - 97 for ch in target]
        cnts = []
        for s in stickers:
            c = [0] * 26
            for ch in s:
                c[ord(ch) - 97] += 1
            cnts.append(c)
        dp = [-1] * (1 << n)
        dp[0] = 0
        for mask in range(full):
            if dp[mask] < 0:
                continue
            first = next(j for j in range(n) if not mask >> j & 1)
            for c in cnts:
                if not c[t[first]]:
                    continue
                c, nm = c[:], mask
                for j in range(n):
                    if not mask >> j & 1 and c[t[j]]:
                        c[t[j]] -= 1
                        nm |= 1 << j
                if dp[nm] < 0 or dp[nm] > dp[mask] + 1:
                    dp[nm] = dp[mask] + 1
        return dp[full]

