class Solution {
public:
    int minStickers(vector<string>& stickers, string target) {
        int n = target.size(), full = (1 << n) - 1;
        vector<array<int, 26>> cnts;
        for (auto& s : stickers) {
            array<int, 26> c{};
            for (char ch : s) c[ch - 'a']++;
            cnts.push_back(c);
        }
        vector<int> dp(1 << n, -1);
        dp[0] = 0;
        for (int mask = 0; mask < full; mask++) {
            if (dp[mask] < 0) continue;
            int first = 0;
            while (mask >> first & 1) first++;
            for (auto c : cnts) {
                if (!c[target[first] - 'a']) continue;
                int nm = mask;
                for (int j = 0; j < n; j++)
                    if (!(mask >> j & 1) && c[target[j] - 'a'] > 0) {
                        c[target[j] - 'a']--;
                        nm |= 1 << j;
                    }
                if (dp[nm] < 0 || dp[nm] > dp[mask] + 1) dp[nm] = dp[mask] + 1;
            }
        }
        return dp[full];
    }
};

