    full := 1<<n - 1
    cnts := make([][26]int, len(stickers))
    for s, w := range stickers {
        for i := 0; i < len(w); i++ {
            cnts[s][w[i]-'a']++
        }
    }
    dp := make([]int, 1<<n)
    for i := range dp {
        dp[i] = -1
    }
    dp[0] = 0
    for mask := 0; mask < full; mask++ {
        if dp[mask] < 0 {
            continue
        }
        first := 0
        for mask>>first&1 == 1 {
            first++
        }
        for _, c := range cnts { // c is a copy of the counts
            if c[target[first]-'a'] == 0 {
                continue
            }
            nm := mask
            for j := 0; j < n; j++ {
                t := target[j] - 'a'
                if mask>>j&1 == 0 && c[t] > 0 {
                    c[t]--
                    nm |= 1 << j
                }
            }
            if dp[nm] < 0 || dp[nm] > dp[mask]+1 {
                dp[nm] = dp[mask] + 1
            }
        }
    }
    return dp[full]
}

