class Solution:
    def maxAreaOfIsland(self, grid: List[List[int]]) -> int:
        m, n, best = len(grid), len(grid[0]), 0
        for i in range(m):
            for j in range(n):
                if not grid[i][j]:
                    continue
                grid[i][j], stack, area = 0, [(i, j)], 0
                while stack:
                    x, y = stack.pop()
                    area += 1
                    for nx, ny in ((x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)):
                        if 0 <= nx < m and 0 <= ny < n and grid[nx][ny]:
                            grid[nx][ny] = 0
                            stack.append((nx, ny))
                best = max(best, area)
        return best

