func (this *KthLargest) Add(val int) int {
	if this.h.Len() < this.k {
		heap.Push(this.h, val)
	} else if val > this.h.IntSlice[0] {
		this.h.IntSlice[0] = val
		heap.Fix(this.h, 0)
	}
	return this.h.IntSlice[0]
}

