class MyLinkedList {
    struct LNode {
        int val;
        LNode* next;
        LNode(int v, LNode* n = nullptr) : val(v), next(n) {}
    };
    LNode* dummy = new LNode(0);
    int size = 0;

    LNode* prevOf(int index) {  // node right before position index
        LNode* cur = dummy;
        while (index--) cur = cur->next;
        return cur;
    }
public:
    MyLinkedList() {}

    int get(int index) {
        if (index < 0 || index >= size) return -1;
        return prevOf(index)->next->val;
    }

    void addAtHead(int val) { addAtIndex(0, val); }

    void addAtTail(int val) { addAtIndex(size, val); }

    void addAtIndex(int index, int val) {
        if (index > size) return;
        LNode* prev = prevOf(max(index, 0));
        prev->next = new LNode(val, prev->next);
        ++size;
    }

    void deleteAtIndex(int index) {
        if (index < 0 || index >= size) return;
        LNode* prev = prevOf(index);
        LNode* del = prev->next;
        prev->next = del->next;
        delete del;
        --size;
    }
};

