class MyLinkedList {
    private static class LNode {
        int val;
        LNode next;
        LNode(int val, LNode next) { this.val = val; this.next = next; }
    }

    private final LNode dummy = new LNode(0, null);
    private int size = 0;

    public MyLinkedList() {}

    // node right before position index (dummy when index == 0)
    private LNode prevOf(int index) {
        LNode cur = dummy;
        while (index-- > 0) cur = cur.next;
        return cur;
    }

    public int get(int index) {
        if (index < 0 || index >= size) return -1;
        return prevOf(index).next.val;
    }

    public void addAtHead(int val) { addAtIndex(0, val); }

    public void addAtTail(int val) { addAtIndex(size, val); }

    public void addAtIndex(int index, int val) {
        if (index > size) return;
        LNode prev = prevOf(Math.max(index, 0));
        prev.next = new LNode(val, prev.next);
        size++;
    }

    public void deleteAtIndex(int index) {
        if (index < 0 || index >= size) return;
        LNode prev = prevOf(index);
        prev.next = prev.next.next;
        size--;
    }
}

