class Solution:
    def insert(self, head: 'Optional[Node]', insertVal: int) -> 'Node':
        node = Node(insertVal)
        if not head:
            node.next = node
            return node
        cur = head
        while True:
            nxt = cur.next
            if cur.val <= insertVal <= nxt.val:
                break  # normal ascending gap
            if cur.val > nxt.val and (insertVal >= cur.val or insertVal <= nxt.val):
                break  # wrap point: max -> min
            cur = nxt
            if cur is head:
                break  # all values equal or no gap fits: any spot works
        node.next = cur.next
        cur.next = node
        return head

