class Solution {
public:
    string simplifyPath(string path) {
        vector<string> stk;
        stringstream ss(path);
        string part;
        while (getline(ss, part, '/')) {
            if (part == "..") { if (!stk.empty()) stk.pop_back(); }
            else if (!part.empty() && part != ".") stk.push_back(part);
        }
        string ans;
        for (auto& s : stk) ans += "/" + s;
        return ans.empty() ? "/" : ans;
    }
};

