class Solution {
    public int smallestDistancePair(int[] nums, int k) {
        Arrays.sort(nums);
        int lo = 0, hi = nums[nums.length - 1] - nums[0];
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (count(nums, mid) >= k) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    }

    // number of pairs with distance <= d
    private long count(int[] nums, int d) {
        long cnt = 0;
        for (int left = 0, right = 0; right < nums.length; right++) {
            while (nums[right] - nums[left] > d) left++;
            cnt += right - left;
        }
        return cnt;
    }
}

