import "sort"

func smallestDistancePair(nums []int, k int) int {
	sort.Ints(nums)
	// count returns the number of pairs with distance <= d
	count := func(d int) int {
		cnt, left := 0, 0
		for right := range nums {
			for nums[right]-nums[left] > d {
				left++
			}
			cnt += right - left
		}
		return cnt
	}
	lo, hi := 0, nums[len(nums)-1]-nums[0]
	for lo < hi {
		mid := (lo + hi) / 2
		if count(mid) >= k {
			hi = mid
		} else {
			lo = mid + 1
		}
	}
	return lo
}

