class Solution {
    vector<int> parent;
    int find(int x) {
        while (parent[x] != x) x = parent[x] = parent[parent[x]];
        return x;
    }
public:
    vector<vector<string>> accountsMerge(vector<vector<string>>& accounts) {
        int n = accounts.size();
        parent.resize(n);
        iota(parent.begin(), parent.end(), 0);
        unordered_map<string, int> owner;
        for (int i = 0; i < n; ++i)
            for (int j = 1; j < (int)accounts[i].size(); ++j) {
                auto it = owner.find(accounts[i][j]);
                if (it != owner.end()) parent[find(i)] = find(it->second);
                else owner[accounts[i][j]] = i;
            }
        unordered_map<int, vector<string>> groups;
        for (auto& [email, i] : owner) groups[find(i)].push_back(email);
        vector<vector<string>> ans;
        for (auto& [root, emails] : groups) {
            sort(emails.begin(), emails.end());
            vector<string> row{accounts[root][0]};
            row.insert(row.end(), emails.begin(), emails.end());
            ans.push_back(std::move(row));
        }
        return ans;
    }
};

