        for (int i = 0; i < n; i++) parent[i] = i;
        Map<String, Integer> owner = new HashMap<>(); // email -> first account index that has it
        for (int i = 0; i < n; i++) {
            List<String> acc = accounts.get(i);
            for (int j = 1; j < acc.size(); j++) {
                Integer o = owner.get(acc.get(j));
                if (o != null) parent[find(i)] = find(o);
                else owner.put(acc.get(j), i);
            }
        }
        Map<Integer, List<String>> groups = new HashMap<>();
        for (Map.Entry<String, Integer> e : owner.entrySet())
            groups.computeIfAbsent(find(e.getValue()), r -> new ArrayList<>()).add(e.getKey());
        List<List<String>> ans = new ArrayList<>();
        for (Map.Entry<Integer, List<String>> e : groups.entrySet()) {
            List<String> emails = e.getValue();
            Collections.sort(emails);
            List<String> row = new ArrayList<>();
            row.add(accounts.get(e.getKey()).get(0));
            row.addAll(emails);
            ans.add(row);
        }
        return ans;
    }
}

