    def countOfAtoms(self, formula: str) -> str:
        n = len(formula)
        i = 0

        def read_num() -> int:
            nonlocal i
            j = i
            while i < n and formula[i].isdigit():
                i += 1
            return int(formula[j:i]) if i > j else 1

        stack = [Counter()]
        while i < n:
            c = formula[i]
            if c == '(':
                stack.append(Counter())
                i += 1
            elif c == ')':
                i += 1
                mult = read_num()
                top = stack.pop()
