class Solution {
public:
    string countOfAtoms(string formula) {
        int n = formula.size(), i = 0;
        auto readNum = [&]() {
            int j = i;
            while (i < n && isdigit(formula[i])) ++i;
            return i > j ? stoi(formula.substr(j, i - j)) : 1;
        };
        vector<map<string, int>> stk(1);
        while (i < n) {
            char c = formula[i];
            if (c == '(') {
                stk.emplace_back();
                ++i;
            } else if (c == ')') {
                ++i;
                int mult = readNum();
                auto top = std::move(stk.back());
                stk.pop_back();
                for (auto& [atom, cnt] : top) stk.back()[atom] += cnt * mult;
            } else {
                int j = i++;
                while (i < n && islower(formula[i])) ++i;
                string atom = formula.substr(j, i - j);
                stk.back()[atom] += readNum();
            }
        }
        string ans;
        for (auto& [atom, cnt] : stk[0]) ans += atom + (cnt > 1 ? to_string(cnt) : "");
        return ans;
    }
};

