class Solution {
    private String formula;
    private int i, n;

    private int readNum() {
        int j = i;
        while (i < n && Character.isDigit(formula.charAt(i))) i++;
        return i > j ? Integer.parseInt(formula.substring(j, i)) : 1;
    }

    public String countOfAtoms(String formula) {
        this.formula = formula;
        n = formula.length();
        i = 0;
        Deque<Map<String, Integer>> stack = new ArrayDeque<>();
        stack.push(new HashMap<>());
        while (i < n) {
            char c = formula.charAt(i);
            if (c == '(') {
                stack.push(new HashMap<>());
                i++;
            } else if (c == ')') {
                i++;
                int mult = readNum();
                Map<String, Integer> top = stack.pop();
                for (Map.Entry<String, Integer> e : top.entrySet())
                    stack.peek().merge(e.getKey(), e.getValue() * mult, Integer::sum);
            } else {
                int j = i++;
                while (i < n && Character.isLowerCase(formula.charAt(i))) i++;
                String atom = formula.substring(j, i);
                stack.peek().merge(atom, readNum(), Integer::sum);
            }
        }
        StringBuilder sb = new StringBuilder();
        for (Map.Entry<String, Integer> e : new TreeMap<>(stack.peek()).entrySet()) {
            sb.append(e.getKey());
            if (e.getValue() > 1) sb.append(e.getValue());
        }
        return sb.toString();
    }
}

