import (
	"sort"
	"strconv"
	"strings"
)

func countOfAtoms(formula string) string {
	n, i := len(formula), 0
	readNum := func() int {
		j := i
		for i < n && formula[i] >= '0' && formula[i] <= '9' {
			i++
		}
		if i == j {
			return 1
		}
		v, _ := strconv.Atoi(formula[j:i])
		return v
	}
	stack := []map[string]int{{}}
	for i < n {
		switch c := formula[i]; c {
		case '(':
			stack = append(stack, map[string]int{})
			i++
		case ')':
			i++
			mult := readNum()
			top := stack[len(stack)-1]
			stack = stack[:len(stack)-1]
			for atom, cnt := range top {
				stack[len(stack)-1][atom] += cnt * mult
			}
		default:
			j := i
			i++
			for i < n && formula[i] >= 'a' && formula[i] <= 'z' {
				i++
			}
			atom := formula[j:i]
			stack[len(stack)-1][atom] += readNum()
		}
	}
	cnt := stack[0]
	atoms := make([]string, 0, len(cnt))
	for a := range cnt {
		atoms = append(atoms, a)
	}
	sort.Strings(atoms)
	var sb strings.Builder
	for _, a := range atoms {
		sb.WriteString(a)
		if cnt[a] > 1 {
			sb.WriteString(strconv.Itoa(cnt[a]))
		}
	}
	return sb.String()
}

