func (h distHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *distHeap) Push(x any)        { *h = append(*h, x.([2]int)) }
func (h *distHeap) Pop() any {
	old := *h
	x := old[len(old)-1]
	*h = old[:len(old)-1]
	return x
}

func networkDelayTime(times [][]int, n int, k int) int {
	graph := make([][][2]int, n+1)
	for _, t := range times {
		graph[t[0]] = append(graph[t[0]], [2]int{t[1], t[2]})
	}
	dist := make([]int, n+1)
	for i := range dist {
		dist[i] = math.MaxInt
	}
	dist[k] = 0
	pq := &distHeap{{0, k}}
	for pq.Len() > 0 {
		top := heap.Pop(pq).([2]int)
		d, u := top[0], top[1]
		if d > dist[u] {
			continue
		}
		for _, e := range graph[u] {
			v, w := e[0], e[1]
			if d+w < dist[v] {
				dist[v] = d + w
				heap.Push(pq, [2]int{dist[v], v})
			}
		}
	}
	ans := 0
	for _, d := range dist[1:] {
		ans = max(ans, d)
	}
	if ans == math.MaxInt {
		return -1
	}
	return ans
}

