class Solution {
    public void sortColors(int[] nums) {
        // [0, lo) are 0s, [lo, i) are 1s, (hi, n) are 2s, [i, hi] unknown
        int lo = 0, i = 0, hi = nums.length - 1;
        while (i <= hi) {
            if (nums[i] == 0) swap(nums, lo++, i++);
            else if (nums[i] == 2) swap(nums, i, hi--); // swapped-in value is unseen, don't advance i
            else i++;
        }
    }

    private void swap(int[] a, int i, int j) {
        int t = a[i];
        a[i] = a[j];
        a[j] = t;
    }
}

