func openLock(deadends []string, target string) int {
	seen := map[string]bool{}
	for _, d := range deadends {
		seen[d] = true
	}
	if seen["0000"] {
		return -1
	}
	seen["0000"] = true
	q := []string{"0000"}
	for steps := 0; len(q) > 0; steps++ {
		var next []string
		for _, cur := range q {
			if cur == target {
				return steps
			}
			for i := 0; i < 4; i++ {
				for _, delta := range []byte{1, 9} {
					b := []byte(cur)
					b[i] = '0' + (cur[i]-'0'+delta)%10
					if nxt := string(b); !seen[nxt] {
						seen[nxt] = true
						next = append(next, nxt)
					}
				}
			}
		}
		q = next
	}
	return -1
}

