        need = Counter(t)
        missing = len(t)
        best_l, best_len = 0, len(s) + 1
        left = 0
        for right, ch in enumerate(s):
            if need[ch] > 0:
                missing -= 1
            need[ch] -= 1
            if missing == 0:
                while need[s[left]] < 0:
                    need[s[left]] += 1
                    left += 1
                if right - left + 1 < best_len:
                    best_l, best_len = left, right - left + 1
                need[s[left]] += 1
                missing += 1
                left += 1
        return '' if best_len > len(s) else s[best_l:best_l + best_len]

