            if (cnt[i] > 0) pq.offer(new int[]{cnt[i], i});
        StringBuilder res = new StringBuilder();
        int[] held = null; // letter just used, kept out of the heap for one round
        while (!pq.isEmpty()) {
            int[] top = pq.poll();
            res.append((char) ('a' + top[1]));
            if (held != null) pq.offer(held);
            top[0]--;
            held = top[0] > 0 ? top : null;
        }
        return res.length() == s.length() ? res.toString() : "";
    }
}

