import "container/heap"

// letterHeap is a max-heap of (count, letter) pairs.
type letterHeap [][2]int

func (h letterHeap) Len() int           { return len(h) }
func (h letterHeap) Less(i, j int) bool { return h[i][0] > h[j][0] }
func (h letterHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *letterHeap) Push(x any)        { *h = append(*h, x.([2]int)) }
func (h *letterHeap) Pop() any {
	old := *h
	x := old[len(old)-1]
	*h = old[:len(old)-1]
	return x
}

func reorganizeString(s string) string {
	var cnt [26]int
	for i := 0; i < len(s); i++ {
		cnt[s[i]-'a']++
	}
	h := &letterHeap{}
	for c, k := range cnt {
		if k > 0 {
			*h = append(*h, [2]int{k, c})
		}
	}
	heap.Init(h)
	res := make([]byte, 0, len(s))
	held := [2]int{} // letter just used, kept out of the heap for one round
	for h.Len() > 0 {
		top := heap.Pop(h).([2]int)
		res = append(res, byte('a'+top[1]))
		if held[0] > 0 {
			heap.Push(h, held)
		}
		held = [2]int{top[0] - 1, top[1]}
	}
	if len(res) != len(s) {
		return ""
	}
	return string(res)
}

