class Solution {
    public String reorganizeString(String s) {
        int n = s.length();
        int[] cnt = new int[26];
        for (char c : s.toCharArray()) cnt[c - 'a']++;
        int top = 0;
        for (int c = 1; c < 26; c++)
            if (cnt[c] > cnt[top]) top = c;
        if (cnt[top] > (n + 1) / 2) return "";
        char[] res = new char[n];
        // the most frequent letter goes first so it never lands next to itself
        int i = place(res, cnt, top, 0);
        for (int c = 0; c < 26; c++) i = place(res, cnt, c, i);
        return new String(res);
    }

    // fill even slots, then wrap to odd slots
    private int place(char[] res, int[] cnt, int c, int i) {
        for (; cnt[c] > 0; cnt[c]--) {
            res[i] = (char) ('a' + c);
            i += 2;
            if (i >= res.length) i = 1;
        }
        return i;
    }
}

