class Solution {
    private String s;
    private int i;

    public int calculate(String s) {
        this.s = s;
        i = 0;
        return (int) helper();
    }

    // evaluates until the matching ')' or the end of the string
    private long helper() {
        List<Long> st = new ArrayList<>();
        long num = 0;
        char op = '+';
        while (i < s.length()) {
            char ch = s.charAt(i++);
            if (Character.isDigit(ch)) num = num * 10 + (ch - '0');
            else if (ch == '(') num = helper();
            else if (ch != ' ') {
                apply(st, op, num);
                if (ch == ')') return sum(st);
                op = ch;
                num = 0;
            }
        }
        apply(st, op, num);
        return sum(st);
    }

    private static void apply(List<Long> st, char op, long num) {
        int last = st.size() - 1;
        if (op == '+') st.add(num);
        else if (op == '-') st.add(-num);
        else if (op == '*') st.set(last, st.get(last) * num);
        else st.set(last, st.get(last) / num);
    }

    private static long sum(List<Long> st) {
        long total = 0;
        for (long x : st) total += x;
        return total;
    }
}

