func calculate(s string) int {
	i := 0
	apply := func(stack []int, op byte, num int) []int {
		switch op {
		case '+':
			return append(stack, num)
		case '-':
			return append(stack, -num)
		case '*':
			stack[len(stack)-1] *= num
		default:
			stack[len(stack)-1] /= num
		}
		return stack
	}
	sum := func(stack []int) int {
		total := 0
		for _, x := range stack {
			total += x
		}
		return total
	}
	// helper evaluates until the matching ')' or the end of the string
	var helper func() int
	helper = func() int {
		var stack []int
		num, op := 0, byte('+')
		for i < len(s) {
			ch := s[i]
			i++
			switch {
			case ch >= '0' && ch <= '9':
				num = num*10 + int(ch-'0')
			case ch == '(':
				num = helper()
			case ch != ' ':
				stack = apply(stack, op, num)
				if ch == ')' {
					return sum(stack)
				}
				op, num = ch, 0
			}
		}
		stack = apply(stack, op, num)
		return sum(stack)
	}
	return helper()
