import "strings"

func slidingPuzzle(board [][]int) int {
	nbr := [][]int{{1, 3}, {0, 2, 4}, {1, 5}, {0, 4}, {1, 3, 5}, {2, 4}}
	b := make([]byte, 0, 6)
	for _, row := range board {
		for _, x := range row {
			b = append(b, byte('0'+x))
		}
	}
	start := string(b)
	seen := map[string]bool{start: true}
	q := []string{start}
	for steps := 0; len(q) > 0; steps++ {
		var next []string
		for _, cur := range q {
			if cur == "123450" {
				return steps
			}
			z := strings.IndexByte(cur, '0')
			for _, j := range nbr[z] {
				t := []byte(cur)
				t[z], t[j] = t[j], t[z]
				if nxt := string(t); !seen[nxt] {
					seen[nxt] = true
					next = append(next, nxt)
				}
			}
		}
		q = next
	}
	return -1
}

