	for r := 0; r <= k; r++ {
		nd := append([]int{}, dist...) // relax from last round's values only
		for _, f := range flights {
			if u, v, w := f[0], f[1], f[2]; dist[u] != math.MaxInt && dist[u]+w < nd[v] {
				nd[v] = dist[u] + w
			}
		}
		dist = nd
	}
	if dist[dst] == math.MaxInt {
		return -1
	}
	return dist[dst]
