            int[] cur = pq.poll();
            int cost = cur[0], u = cur[1], used = cur[2];
            if (u == dst) return cost;
            if (used >= bestUsed[u] || used > k) continue;
            bestUsed[u] = used;
            for (int[] e : g.get(u)) pq.offer(new int[]{cost + e[1], e[0], used + 1});
