import (
	"container/heap"
	"math"
)

type stateHeap [][3]int // (cost, city, flights used)

func (h stateHeap) Len() int           { return len(h) }
func (h stateHeap) Less(i, j int) bool { return h[i][0] < h[j][0] }
func (h stateHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *stateHeap) Push(x any)        { *h = append(*h, x.([3]int)) }
func (h *stateHeap) Pop() any {
	old := *h
	x := old[len(old)-1]
	*h = old[:len(old)-1]
	return x
}

func findCheapestPrice(n int, flights [][]int, src int, dst int, k int) int {
	g := make([][][2]int, n)
	for _, f := range flights {
		g[f[0]] = append(g[f[0]], [2]int{f[1], f[2]})
	}
	bestUsed := make([]int, n) // fewest flights used when each city was popped
	for i := range bestUsed {
		bestUsed[i] = math.MaxInt
	}
	pq := &stateHeap{{0, src, 0}}
	for pq.Len() > 0 {
		cur := heap.Pop(pq).([3]int)
		cost, u, used := cur[0], cur[1], cur[2]
		if u == dst {
			return cost
		}
		if used >= bestUsed[u] || used > k {
			continue
		}
		bestUsed[u] = used
		for _, e := range g[u] {
			heap.Push(pq, [3]int{cost + e[1], e[0], used + 1})
		}
	}
	return -1
}

