            found = any(0 <= nr < m and 0 <= nc < n and dfs(nr, nc, i + 1)
                        for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)))
            board[r][c] = word[i]
            return found

        return any(dfs(r, c, 0) for r in range(m) for c in range(n))

