class Solution {
    private char[][] board;
    private char[] w;
    private int m, n;

    public boolean exist(char[][] board, String word) {
        this.board = board;
        m = board.length;
        n = board[0].length;
        int[] cnt = new int[128], need = new int[128];
        for (char[] row : board)
            for (char ch : row) cnt[ch]++;
        for (char ch : word.toCharArray()) need[ch]++;
        for (int ch = 0; ch < 128; ch++)
            if (cnt[ch] < need[ch]) return false;
        w = word.toCharArray();
        // start from the rarer end so dead branches die sooner
        if (cnt[w[0]] > cnt[w[w.length - 1]]) w = new StringBuilder(word).reverse().toString().toCharArray();
        for (int r = 0; r < m; r++)
            for (int c = 0; c < n; c++)
                if (dfs(r, c, 0)) return true;
        return false;
    }

    private boolean dfs(int r, int c, int i) {
        if (r < 0 || c < 0 || r >= m || c >= n || board[r][c] != w[i]) return false;
        if (i == w.length - 1) return true;
        board[r][c] = '#';
        boolean found = dfs(r + 1, c, i + 1) || dfs(r - 1, c, i + 1)
                || dfs(r, c + 1, i + 1) || dfs(r, c - 1, i + 1);
        board[r][c] = w[i];
        return found;
    }
}

