class Solution {
public:
    vector<int> eventualSafeNodes(vector<vector<int>>& graph) {
        int n = graph.size();
        vector<vector<int>> rev(n);
        vector<int> out(n);
        for (int u = 0; u < n; u++) {
            out[u] = graph[u].size();
            for (int v : graph[u]) rev[v].push_back(u);
        }
        queue<int> q;
        for (int i = 0; i < n; i++)
            if (out[i] == 0) q.push(i);
        vector<bool> safe(n);
        while (!q.empty()) {
            int v = q.front();
            q.pop();
            safe[v] = true;
            for (int u : rev[v])
                if (--out[u] == 0) q.push(u);
        }
        vector<int> res;
        for (int i = 0; i < n; i++)
            if (safe[i]) res.push_back(i);
        return res;
    }
};

