func eventualSafeNodes(graph [][]int) []int {
	n := len(graph)
	rev := make([][]int, n)
	out := make([]int, n)
	for u, vs := range graph {
		out[u] = len(vs)
		for _, v := range vs {
			rev[v] = append(rev[v], u)
		}
	}
	var q []int
	for i := 0; i < n; i++ {
		if out[i] == 0 {
			q = append(q, i)
		}
	}
	safe := make([]bool, n)
	for len(q) > 0 {
		v := q[0]
		q = q[1:]
		safe[v] = true
		for _, u := range rev[v] {
			out[u]--
			if out[u] == 0 {
				q = append(q, u)
			}
		}
	}
	res := []int{}
	for i := 0; i < n; i++ {
		if safe[i] {
			res = append(res, i)
		}
	}
	return res
}

