class Solution:
    def expressiveWords(self, s: str, words: List[str]) -> int:
        def stretchy(w):
            i = j = 0
            while i < len(s) and j < len(w):
                if s[i] != w[j]:
                    return False
                a, b = i, j
                while i < len(s) and s[i] == s[a]:
                    i += 1
                while j < len(w) and w[j] == w[b]:
                    j += 1
                ls, lw = i - a, j - b
                if lw > ls or (ls < 3 and ls != lw):
                    return False
            return i == len(s) and j == len(w)

        return sum(stretchy(w) for w in words)

