class Solution {
    static bool stretchy(const string& s, const string& w) {
        int i = 0, j = 0, n = s.size(), m = w.size();
        while (i < n && j < m) {
            if (s[i] != w[j]) return false;
            int a = i, b = j;
            while (i < n && s[i] == s[a]) i++;
            while (j < m && w[j] == w[b]) j++;
            int ls = i - a, lw = j - b;
            if (lw > ls || (ls < 3 && ls != lw)) return false;
        }
        return i == n && j == m;
    }

public:
    int expressiveWords(string s, vector<string>& words) {
        int res = 0;
        for (auto& w : words) res += stretchy(s, w);
        return res;
    }
};

