    private static boolean stretchy(String s, String w) {
        int i = 0, j = 0, n = s.length(), m = w.length();
        while (i < n && j < m) {
            if (s.charAt(i) != w.charAt(j)) return false;
            int a = i, b = j;
            while (i < n && s.charAt(i) == s.charAt(a)) i++;
            while (j < m && w.charAt(j) == w.charAt(b)) j++;
            int ls = i - a, lw = j - b;
            if (lw > ls || (ls < 3 && ls != lw)) return false;
        }
        return i == n && j == m;
    }
}

