class Solution:
    def numBusesToDestination(self, routes: List[List[int]], source: int, target: int) -> int:
        if source == target:
            return 0
        buses_at = defaultdict(list)
        for i, route in enumerate(routes):
            for stop in route:
                buses_at[stop].append(i)
        used = [False] * len(routes)
        seen = {source}
        q = deque([source])
        buses = 0
        while q:
            buses += 1
            for _ in range(len(q)):
                for b in buses_at[q.popleft()]:
                    if used[b]:
                        continue
                    used[b] = True
                    for nxt in routes[b]:
                        if nxt == target:
                            return buses
                        if nxt not in seen:
                            seen.add(nxt)
                            q.append(nxt)
        return -1

