class Solution {
public:
    int numBusesToDestination(vector<vector<int>>& routes, int source, int target) {
        if (source == target) return 0;
        unordered_map<int, vector<int>> busesAt;
        for (int i = 0; i < (int)routes.size(); i++)
            for (int stop : routes[i]) busesAt[stop].push_back(i);
        vector<bool> used(routes.size());
        unordered_set<int> seen{source};
        queue<int> q;
        q.push(source);
        for (int buses = 1; !q.empty(); buses++) {
            for (int sz = q.size(); sz--;) {
                int stop = q.front();
                q.pop();
                for (int b : busesAt[stop]) {
                    if (used[b]) continue;
                    used[b] = true;
                    for (int nxt : routes[b]) {
                        if (nxt == target) return buses;
                        if (seen.insert(nxt).second) q.push(nxt);
                    }
                }
            }
        }
        return -1;
    }
};

