class Solution {
    public int numBusesToDestination(int[][] routes, int source, int target) {
        if (source == target) return 0;
        Map<Integer, List<Integer>> busesAt = new HashMap<>();
        for (int i = 0; i < routes.length; i++)
            for (int stop : routes[i]) busesAt.computeIfAbsent(stop, x -> new ArrayList<>()).add(i);
        boolean[] used = new boolean[routes.length];
        Set<Integer> seen = new HashSet<>();
        seen.add(source);
        Deque<Integer> q = new ArrayDeque<>();
        q.offer(source);
        for (int buses = 1; !q.isEmpty(); buses++) {
            for (int sz = q.size(); sz > 0; sz--) {
                for (int b : busesAt.getOrDefault(q.poll(), List.of())) {
                    if (used[b]) continue;
                    used[b] = true; // each route is expanded only once
                    for (int nxt : routes[b]) {
                        if (nxt == target) return buses;
                        if (seen.add(nxt)) q.offer(nxt);
                    }
                }
            }
        }
        return -1;
    }
}

