func numBusesToDestination(routes [][]int, source int, target int) int {
	if source == target {
		return 0
	}
	busesAt := map[int][]int{}
	for i, route := range routes {
		for _, stop := range route {
			busesAt[stop] = append(busesAt[stop], i)
		}
	}
	used := make([]bool, len(routes))
	seen := map[int]bool{source: true}
	q := []int{source}
	for buses := 1; len(q) > 0; buses++ {
		var next []int
		for _, stop := range q {
			for _, b := range busesAt[stop] {
				if used[b] {
					continue
				}
				used[b] = true // each route is expanded only once
				for _, nxt := range routes[b] {
					if nxt == target {
						return buses
					}
					if !seen[nxt] {
						seen[nxt] = true
						next = append(next, nxt)
					}
				}
			}
		}
		q = next
	}
	return -1
}

