import "sort"

func maxProfitAssignment(difficulty []int, profit []int, worker []int) int {
	n := len(difficulty)
	jobs := make([][2]int, n)
	for i := range jobs {
		jobs[i] = [2]int{difficulty[i], profit[i]}
	}
	sort.Slice(jobs, func(a, b int) bool { return jobs[a][0] < jobs[b][0] })
	sort.Ints(worker)
	res, best, i := 0, 0, 0
	for _, w := range worker {
		for i < n && jobs[i][0] <= w {
			best = max(best, jobs[i][1])
			i++
		}
		res += best
	}
	return res
}

