class Solution {
    public int maxProfitAssignment(int[] difficulty, int[] profit, int[] worker) {
        int top = 0;
        for (int d : difficulty) top = Math.max(top, d);
        for (int w : worker) top = Math.max(top, w);
        int[] best = new int[top + 1]; // best[x]: max profit of a job with difficulty <= x
        for (int i = 0; i < difficulty.length; i++) best[difficulty[i]] = Math.max(best[difficulty[i]], profit[i]);
        for (int x = 1; x <= top; x++) best[x] = Math.max(best[x], best[x - 1]);
        int res = 0;
        for (int w : worker) res += best[w];
        return res;
    }
}

