import "slices"

func maxProfitAssignment(difficulty []int, profit []int, worker []int) int {
	top := max(slices.Max(difficulty), slices.Max(worker))
	best := make([]int, top+1) // best[x]: max profit of a job with difficulty <= x
	for i, d := range difficulty {
		best[d] = max(best[d], profit[i])
	}
	for x := 1; x <= top; x++ {
		best[x] = max(best[x], best[x-1])
	}
	res := 0
	for _, w := range worker {
		res += best[w]
	}
	return res
}

