        int n = heights.length, best = 0;
        int[] stack = new int[n + 1];
        int top = 0;
        for (int i = 0; i <= n; i++) {
            int x = i == n ? 0 : heights[i]; // trailing 0 flushes the stack
            while (top > 0 && heights[stack[top - 1]] >= x) {
                int height = heights[stack[--top]];
                int left = top > 0 ? stack[top - 1] : -1;
