class Solution:
    def shortestPathLength(self, graph: List[List[int]]) -> int:
        n = len(graph)
        full = (1 << n) - 1
        q = deque((i, 1 << i) for i in range(n))
        seen = set(q)
        dist = 0
        while q:
            for _ in range(len(q)):
                u, mask = q.popleft()
                if mask == full:
                    return dist
                for v in graph[u]:
                    nxt = (v, mask | 1 << v)
                    if nxt not in seen:
                        seen.add(nxt)
                        q.append(nxt)
            dist += 1
        return 0

