func shortestPathLength(graph [][]int) int {
    n := len(graph)
    full := 1<<n - 1
    seen := make([][]bool, n)
    for i := range seen {
        seen[i] = make([]bool, 1<<n)
    }
    type state struct{ u, mask int }
    q := []state{}
    for i := 0; i < n; i++ {
        q = append(q, state{i, 1 << i})
        seen[i][1<<i] = true
    }
    for dist := 0; len(q) > 0; dist++ {
        var next []state
        for _, s := range q {
            if s.mask == full {
                return dist
            }
            for _, v := range graph[s.u] {
                m := s.mask | 1<<v
                if !seen[v][m] {
                    seen[v][m] = true
                    next = append(next, state{v, m})
                }
            }
        }
        q = next
    }
    return 0
}

