    def mincostToHireWorkers(self, quality: List[int], wage: List[int], k: int) -> float:
        workers = sorted(zip(quality, wage), key=lambda p: p[1] / p[0])
        heap, total, best = [], 0, float('inf')
        for q, w in workers:
            heapq.heappush(heap, -q)
            total += q
            if len(heap) > k:
                total += heapq.heappop(heap)  # popped value is -largest quality
            if len(heap) == k:
                best = min(best, total * w / q)
        return best

