import (
    "container/heap"
    "sort"
)

type maxHeap []int

func (h maxHeap) Len() int           { return len(h) }
func (h maxHeap) Less(i, j int) bool { return h[i] > h[j] }
func (h maxHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *maxHeap) Push(x any)        { *h = append(*h, x.(int)) }
func (h *maxHeap) Pop() any {
    old := *h
    x := old[len(old)-1]
    *h = old[:len(old)-1]
    return x
}

func mincostToHireWorkers(quality []int, wage []int, k int) float64 {
    n := len(quality)
    idx := make([]int, n)
    for i := range idx {
        idx[i] = i
    }
    // sort by wage/quality ratio without floating point
    sort.Slice(idx, func(a, b int) bool {
        x, y := idx[a], idx[b]
        return wage[x]*quality[y] < wage[y]*quality[x]
    })
    h := &maxHeap{}
    total, best := 0, 1e18
    for _, i := range idx {
        heap.Push(h, quality[i])
        total += quality[i]
        if h.Len() > k {
            total -= heap.Pop(h).(int)
        }
        if h.Len() == k {
            best = min(best, float64(total)*float64(wage[i])/float64(quality[i]))
        }
    }
    return best
}

