/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode(int x) : val(x), left(NULL), right(NULL) {}
 * };
 */
class Solution {
public:
    vector<int> distanceK(TreeNode* root, TreeNode* target, int k) {
        unordered_map<TreeNode*, TreeNode*> parent{{root, nullptr}};
        vector<TreeNode*> stk{root};
        while (!stk.empty()) {
            TreeNode* node = stk.back();
            stk.pop_back();
            for (TreeNode* child : {node->left, node->right})
                if (child) {
                    parent[child] = node;
                    stk.push_back(child);
                }
        }
        queue<TreeNode*> q;
        unordered_set<TreeNode*> seen{target};
        q.push(target);
        for (int d = 0; d < k && !q.empty(); ++d) {
            for (int s = q.size(); s > 0; --s) {
                TreeNode* node = q.front();
                q.pop();
                for (TreeNode* nb : {node->left, node->right, parent[node]})
                    if (nb && seen.insert(nb).second) q.push(nb);
            }
        }
        vector<int> res;
        for (; !q.empty(); q.pop()) res.push_back(q.front()->val);
        return res;
    }
};

