class Solution {
    void sift(vector<int>& a, int i, int size) {
        while (true) {
            int big = i, l = 2 * i + 1, r = 2 * i + 2;
            if (l < size && a[l] > a[big]) big = l;
            if (r < size && a[r] > a[big]) big = r;
            if (big == i) return;
            swap(a[i], a[big]);
            i = big;
        }
    }
