        ListNode cur = pre.next;
        // move the node after cur to the front of the sublist, right - left times
        for (int i = left; i < right; i++) {
            ListNode nxt = cur.next;
            cur.next = nxt.next;
            nxt.next = pre.next;
            pre.next = nxt;
