        vector<pair<int, int>> stk;
        for (int i = 0; i < n && stk.empty(); ++i)
            for (int j = 0; j < n && stk.empty(); ++j)
                if (grid[i][j]) { grid[i][j] = 2; stk.push_back({i, j}); }
