        while (!stk.empty()) {
            auto [i, j] = stk.back();
            stk.pop_back();
            q.push({i, j});
            for (int d = 0; d < 4; ++d) {
                int x = i + dx[d], y = j + dy[d];
                if (x >= 0 && x < n && y >= 0 && y < n && grid[x][y] == 1) {
                    grid[x][y] = 2;
                    stk.push_back({x, y});
