        cell := stk[len(stk)-1]
        stk = stk[:len(stk)-1]
        q = append(q, cell)
        for _, d := range dirs {
            x, y := cell[0]+d[0], cell[1]+d[1]
            if x >= 0 && x < n && y >= 0 && y < n && grid[x][y] == 1 {
                grid[x][y] = 2
                stk = append(stk, [2]int{x, y})
            }
        }
    }
