            if (stk.isEmpty() || nums[stk.peek()] > nums[i]) stk.push(i);
        int res = 0;
        for (int j = n - 1; j >= 0; j--) {
            while (!stk.isEmpty() && nums[stk.peek()] <= nums[j]) {
                res = Math.max(res, j - stk.pop());
