class TimeMap {
    private static class Entry {
        final int time;
        final String value;

        Entry(int time, String value) {
            this.time = time;
            this.value = value;
        }
    }

    // timestamps arrive strictly increasing per key, so each list stays sorted
    private final Map<String, List<Entry>> data = new HashMap<>();

    public TimeMap() {}

    public void set(String key, String value, int timestamp) {
        data.computeIfAbsent(key, k -> new ArrayList<>()).add(new Entry(timestamp, value));
    }

    public String get(String key, int timestamp) {
        List<Entry> v = data.get(key);
        if (v == null) return "";
        // first index whose time exceeds timestamp
        int lo = 0, hi = v.size();
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (v.get(mid).time <= timestamp) lo = mid + 1;
            else hi = mid;
        }
        return lo == 0 ? "" : v.get(lo - 1).value;
    }
}

