        Deque<TreeNode> stk = new ArrayDeque<>();
        TreeNode cur = root, prev = null, first = null, second = null;
        while (cur != null || !stk.isEmpty()) {
            while (cur != null) {
                stk.push(cur);
                cur = cur.left;
            }
            cur = stk.pop();
            if (prev != null && prev.val > cur.val) {
                if (first == null) first = prev;
                second = cur;
            }
            prev = cur;
            cur = cur.right;
        }
        int t = first.val;
        first.val = second.val;
        second.val = t;
    }
}

