class Solution:
    def subarraysWithKDistinct(self, nums: List[int], k: int) -> int:
        def at_most(k: int) -> int:
            cnt = [0] * (len(nums) + 1)
            res = l = distinct = 0
            for r, x in enumerate(nums):
                if cnt[x] == 0:
                    distinct += 1
                cnt[x] += 1
                while distinct > k:
                    cnt[nums[l]] -= 1
                    if cnt[nums[l]] == 0:
                        distinct -= 1
                    l += 1
                res += r - l + 1
            return res

        return at_most(k) - at_most(k - 1)

