func subarraysWithKDistinct(nums []int, k int) int {
    // number of subarrays with at most k distinct values (values are in 1..n)
    atMost := func(k int) int {
        cnt := make([]int, len(nums)+1)
        res, l, distinct := 0, 0, 0
        for r, x := range nums {
            if cnt[x] == 0 {
                distinct++
            }
            cnt[x]++
            for distinct > k {
                cnt[nums[l]]--
                if cnt[nums[l]] == 0 {
                    distinct--
                }
                l++
            }
            res += r - l + 1
        }
        return res
    }
    return atMost(k) - atMost(k-1)
}

