func orangesRotting(grid [][]int) int {
    m, n := len(grid), len(grid[0])
    fresh, minutes := 0, 0
    var q [][2]int
    for i := 0; i < m; i++ {
        for j := 0; j < n; j++ {
            if grid[i][j] == 2 {
                q = append(q, [2]int{i, j})
            } else if grid[i][j] == 1 {
                fresh++
            }
        }
    }
    dirs := [4][2]int{{1, 0}, {-1, 0}, {0, 1}, {0, -1}}
    for len(q) > 0 && fresh > 0 {
        minutes++
        var next [][2]int
        for _, cell := range q {
            for _, d := range dirs {
                x, y := cell[0]+d[0], cell[1]+d[1]
                if x >= 0 && x < m && y >= 0 && y < n && grid[x][y] == 1 {
                    grid[x][y] = 2
                    fresh--
                    next = append(next, [2]int{x, y})
                }
            }
        }
        q = next
    }
    if fresh > 0 {
        return -1
    }
    return minutes
}
